//! Identity-constitution suites (bead fgdb-g0-identity-registries-hrx).
//!
//! Named suites required by the bead's acceptance criteria:
//!   idr_schema_valid_all_six, idr_disjointness_no_dual_class,
//!   idr_code_space_retired_reuse_fails,
//!   idr_code_space_experimental_in_production_fails,
//!   idr_construction_dag_acyclic (+ negatives idr_neg_self_edge,
//!   idr_neg_mutual_edge, idr_neg_future_result_edge),
//!   idr_bodydigest_recipe_roundtrip, idr_neg_unregistered_field_unencodable,
//!   idr_reserved_w12_coverage, idr_reference_targets_resolve (property),
//!   idr_golden_vector_mutation (fuzz).
//!
//! Suites run against the REAL `registries/` identity artifacts plus
//! targeted in-memory mutations, so a defect in the shipped registries and a
//! defect in the checker are both build breaks.

use registry_check::appendix_a::{self, Catalog, Violation};
use registry_check::appendix_source;
use registry_check::architecture;
use registry_check::identity::{
    self, BUILTIN_WIRE_TYPES, FieldRow, IdentityRegistries, LogicalKind, WireType, bodydigest_pin,
    bodydigest_transcript,
};
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("repo root resolves")
}

#[test]
fn idr_dgtv_registered_strong_ref_bodyless_marker_accounting_is_exact() {
    use registry_check::appendix_source::{
        DefinitionKind, SourceSliceSpec, census_appendix_source,
    };

    let catalog = real_appendix_catalog();
    let plan = real_plan_source();
    let appendix = source_range(
        &plan,
        catalog.source_manifest.start_line,
        catalog.source_manifest.end_line,
    );
    let specs = catalog
        .slices
        .iter()
        .map(|slice| SourceSliceSpec {
            id: &slice.id,
            start_line: usize::try_from(slice.start_line).expect("slice start fits"),
            end_line: usize::try_from(slice.end_line).expect("slice end fits"),
        })
        .collect::<Vec<_>>();
    let census = census_appendix_source(
        &appendix,
        usize::try_from(catalog.source_manifest.start_line).expect("source start fits"),
        &specs,
    )
    .expect("source census");

    // A structural-body marker is a source line whose definition key itself
    // opens a body.  RegisteredStrongRef occurs only as generated by-value
    // vocabulary inside other schemas; it never opens such a body.
    let present = String::from_utf8_lossy(&appendix)
        .lines()
        .filter(|line| {
            let trimmed = line.trim_start();
            trimmed.starts_with("RegisteredStrongRef") && trimmed.contains('{')
        })
        .count();
    let consumed = census
        .schemas
        .iter()
        .filter(|schema| schema.key.source_key() == "top|RegisteredStrongRef")
        .filter(|schema| {
            schema.definition_kinds.iter().any(|kind| {
                matches!(
                    kind,
                    DefinitionKind::FencedRecord
                        | DefinitionKind::InlineRecord
                        | DefinitionKind::ProseLinkedStructural
                        | DefinitionKind::BoldOwnerStructural
                )
            })
        })
        .count();
    assert_eq!(present, 0, "RegisteredStrongRef structural markers present");
    assert_eq!(
        consumed,
        0,
        "RegisteredStrongRef structural markers consumed: {:?}",
        census
            .schemas
            .iter()
            .filter(|schema| schema.key.source_key() == "top|RegisteredStrongRef")
            .collect::<Vec<_>>()
    );
    assert_eq!(
        census
            .fields
            .iter()
            .filter(|field| field.key.schema_family == "RegisteredStrongRef")
            .count(),
        0,
        "bodyless vocabulary must emit no interior field rows"
    );
    assert_eq!(
        registry_check::appendix_source::AmbiguityKind::DefinitionWithoutStructuralBody.as_str(),
        "definition-without-structural-body",
        "bodyless-schema guard code must remain explicit"
    );
}

fn real_identity() -> IdentityRegistries {
    identity::load_identity(&repo_root().join("registries")).expect("identity registries load")
}

fn real_appendix_catalog_text() -> String {
    std::fs::read_to_string(repo_root().join(appendix_a::CATALOG_PATH))
        .expect("Appendix A catalog is readable")
}

fn real_appendix_catalog() -> Catalog {
    appendix_a::parse_catalog(&real_appendix_catalog_text()).expect("Appendix A catalog parses")
}

fn real_plan_source() -> Vec<u8> {
    std::fs::read(repo_root().join(appendix_a::PLAN_PATH)).expect("plan source is readable")
}

fn source_range(source: &[u8], start_line: i64, end_line: i64) -> Vec<u8> {
    let skip = usize::try_from(start_line - 1).expect("positive source line");
    let take = usize::try_from(end_line - start_line + 1).expect("ordered source range");
    source
        .split_inclusive(|byte| *byte == b'\n')
        .skip(skip)
        .take(take)
        .flatten()
        .copied()
        .collect()
}

#[test]
fn idr_a21_decision_policy_epoch_source_and_active_field_table_are_exact() {
    let catalog = real_appendix_catalog();
    let plan = real_plan_source();
    let appendix = source_range(
        &plan,
        catalog.source_manifest.start_line,
        catalog.source_manifest.end_line,
    );
    let specs = catalog
        .slices
        .iter()
        .map(|slice| appendix_source::SourceSliceSpec {
            id: &slice.id,
            start_line: usize::try_from(slice.start_line).expect("slice start fits"),
            end_line: usize::try_from(slice.end_line).expect("slice end fits"),
        })
        .collect::<Vec<_>>();
    let census = appendix_source::census_appendix_source(
        &appendix,
        usize::try_from(catalog.source_manifest.start_line).expect("source start fits"),
        &specs,
    )
    .expect("source census");
    let observed_source_keys = census
        .schemas
        .iter()
        .map(|row| row.key.source_key())
        .chain(census.fields.iter().map(|row| row.key.source_key()))
        .filter(|key| key.contains("DecisionPolicyEpoch"))
        .collect::<Vec<_>>();
    assert!(
        observed_source_keys.is_empty(),
        "the terminal A21 prose deliberately requires explicit projection fallbacks; it must not silently become a second structurally parsed authority: {observed_source_keys:?}"
    );

    let registries = real_identity();
    let logical = registries
        .logical
        .iter()
        .find(|row| row.name == "DecisionPolicyEpoch")
        .expect("DecisionPolicyEpoch logical kind");
    assert_eq!(logical.object_kind, 0x0582);
    assert_eq!(logical.status, "active");
    assert_eq!(logical.construction_order, 30);
    assert_eq!(logical.role_predicate, "true");
    assert_eq!(logical.max_size_bytes, 131_543);

    let observed_fields = registries
        .fields
        .iter()
        .filter(|row| row.containing_schema == "DecisionPolicyEpoch")
        .map(|row| {
            (
                row.field_tag,
                row.stable_name.as_str(),
                row.exact_wire_type.as_str(),
                row.cardinality.as_str(),
                row.identity_class.as_str(),
                row.reference_semantics.as_str(),
                row.version_status.as_str(),
                row.max_size_bytes,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        observed_fields,
        [
            (
                0x0001,
                "policy_id",
                "string",
                "one",
                "scalar",
                "none",
                "active",
                256
            ),
            (
                0x0002, "version", "u64", "one", "scalar", "none", "active", 8
            ),
            (
                0x0003,
                "scope",
                "oid256",
                "one",
                "logical",
                "weak_digest",
                "active",
                32
            ),
            (
                0x0004,
                "logical_effect_class",
                "LogicalEffectClass",
                "one",
                "inline",
                "none",
                "active",
                1
            ),
            (
                0x0005,
                "pinned_table_oid",
                "oid256",
                "one",
                "logical",
                "weak_digest",
                "active",
                32
            ),
            (
                0x0006,
                "fallback_oid",
                "oid256",
                "one",
                "logical",
                "weak_digest",
                "active",
                32
            ),
            (
                0x0007,
                "evidence_refs",
                "oid256",
                "many",
                "logical",
                "weak_digest",
                "active",
                32
            ),
            (
                0x0008,
                "previous_epoch_oid",
                "oid256",
                "optional",
                "logical",
                "weak_digest",
                "active",
                33
            ),
        ],
        "the implementation's canonical tags and the durable field table must remain one exact contract"
    );

    let observed_effect_types = registries
        .wire
        .iter()
        .filter(|row| {
            row.name == "LogicalEffectClass" || row.name.starts_with("LogicalEffectClass.")
        })
        .map(|row| {
            (
                row.wire_type_id,
                row.name.as_str(),
                row.kind.as_str(),
                row.containing_union.as_deref(),
                row.wire_tag,
                row.status.as_str(),
                row.max_size_bytes,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        observed_effect_types,
        [
            (
                0x0574,
                "LogicalEffectClass",
                "discriminant",
                None,
                None,
                "active",
                1
            ),
            (
                0x0575,
                "LogicalEffectClass.answer_preserving_physical",
                "union_variant",
                Some("LogicalEffectClass"),
                Some(0x0001),
                "active",
                1
            ),
            (
                0x0576,
                "LogicalEffectClass.answer_affecting_execution",
                "union_variant",
                Some("LogicalEffectClass"),
                Some(0x0002),
                "active",
                1
            ),
            (
                0x0577,
                "LogicalEffectClass.canonical_state_affecting",
                "union_variant",
                Some("LogicalEffectClass"),
                Some(0x0003),
                "active",
                1
            ),
        ],
        "LogicalEffectClass must remain the closed three-tag durable vocabulary implemented by policy_epoch.rs"
    );
}

fn line_start_offset(source: &[u8], line: i64) -> usize {
    let preceding = usize::try_from(line - 1).expect("positive source line");
    source
        .split_inclusive(|byte| *byte == b'\n')
        .take(preceding)
        .map(<[u8]>::len)
        .sum()
}

fn has_violation(violations: &[Violation], code: &str, detail: &str) -> bool {
    violations
        .iter()
        .any(|violation| violation.code == code && violation.msg.contains(detail))
}

fn duplicate_slice(catalog: &mut Catalog) {
    catalog.slices[1].id = catalog.slices[0].id.clone();
}

fn reorder_slices(catalog: &mut Catalog) {
    catalog.slices.swap(0, 1);
}

fn gap_slices(catalog: &mut Catalog) {
    catalog.slices[1].start_line += 1;
}

fn off_by_one_manifest(catalog: &mut Catalog) {
    catalog.source_manifest.end_line -= 1;
}

fn wrong_slice_bead(catalog: &mut Catalog) {
    catalog.slices[10].bead_id.push_str("-wrong");
}

fn wrong_manifest_hash(catalog: &mut Catalog) {
    catalog.source_manifest.sha256.replace_range(0..1, "0");
}

fn wrong_slice_hash(catalog: &mut Catalog) {
    catalog.slices[10].sha256.replace_range(0..1, "0");
}

fn swap_first_two_table_blocks(source: &str, header: &str) -> String {
    let first = source.find(header).expect("first table block exists");
    let second = first
        + header.len()
        + source[first + header.len()..]
            .find(header)
            .expect("second table block exists");
    let third = second
        + header.len()
        + source[second + header.len()..]
            .find(header)
            .expect("third table block exists");

    let mut reordered = String::with_capacity(source.len());
    reordered.push_str(&source[..first]);
    reordered.push_str(&source[second..third]);
    reordered.push_str(&source[first..second]);
    reordered.push_str(&source[third..]);
    reordered
}

fn codes(r: &IdentityRegistries) -> Vec<String> {
    identity::validate_identity(r)
        .into_iter()
        .map(|v| v.code)
        .collect()
}

/// A synthetic field row with sane defaults for mutation fixtures.
fn field(containing: &str, tag: i64, name: &str, order: i64) -> FieldRow {
    FieldRow {
        containing_schema: containing.into(),
        field_tag: tag,
        stable_name: name.into(),
        exact_wire_type: "StrongRef".into(),
        cardinality: "one".into(),
        identity_class: "logical".into(),
        reference_semantics: "strong".into(),
        target_schema_id: None,
        construction_order: order,
        construction_relation: None,
        role_predicate: "true".into(),
        retention_and_cut_rule: "fixture".into(),
        version_status: "active".into(),
        max_size_bytes: 40,
        digest_class: None,
        transcript_recipe: None,
        bd_domain_separator: None,
        bd_schema_major: None,
        bd_included_field_tags: None,
        bd_excluded_field_tags: None,
        recipe_pin: None,
    }
}

fn kind(code: i64, name: &str, status: &str, order: i64) -> LogicalKind {
    LogicalKind {
        object_kind: code,
        name: name.into(),
        status: status.into(),
        construction_order: order,
        role_predicate: "true".into(),
        max_size_bytes: 4096,
        golden_corpus: "corpus/fixture/".into(),
    }
}

/// The synthetic ordinary-union corpus, with the durable-fields epoch left as a
/// placeholder that is substituted from the SHIPPED registry.
///
/// `@EPOCH@` is not valid TOML, so a substitution that stops happening is a loud
/// parse failure rather than a silent divergence.
const ORDINARY_UNION_FIXTURE_SOURCE: &str = r#"
schema_version = 1

[registry]
name = "durable_fields"
registry_epoch = @EPOCH@

[[union]]
union_name = "FixtureTopLevelUnion"
containing_schema = "RootBootstrap"
union_path = "fixture_top_level_union"
tag_wire_type = "u8"
encoding_context = "closed-tagged"
allowed_containing_schemas = ["RootBootstrap"]
role_predicate = "true"
version_status = "active"
max_size_bytes = 128

[[union_arm]]
union_name = "FixtureTopLevelUnion"
containing_schema = "RootBootstrap"
union_path = "fixture_top_level_union"
arm_tag = 1
source_arm_name = "Absent"
stable_name = "absent"
payload_kind = "unit"
role_predicate = "true"
version_status = "active"
max_size_bytes = 1

[[union_arm]]
union_name = "FixtureTopLevelUnion"
containing_schema = "RootBootstrap"
union_path = "fixture_top_level_union"
arm_tag = 2
source_arm_name = "Present"
stable_name = "present"
payload_kind = "inline-record"
payload_sha256 = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
role_predicate = "true"
version_status = "active"
max_size_bytes = 127
"#;

/// Real identity plus one synthetic top-level union, for the eleven tests that
/// mutate that union and assert the code it draws.
///
/// THE EPOCH IS DERIVED, NEVER RETYPED (fgdb-un4g). It was a literal, and the
/// cost was measured: `durable_fields` advanced 68 -> 69 and eleven consumers of
/// this fixture went red at once, because the stitching below overwrites
/// `identity.fields_epoch` with the fixture's value and every consumer then saw
/// a `registry_epoch_mismatch` it was never testing for. Reproduced on demand at
/// b77982e -- put the literal back and exactly those eleven fail again, no more
/// and no fewer. Advancing the literal by hand fixed one epoch and left the next
/// to reproduce it: 8e5cd57 bumped 68 -> 69 and bf9604c had to bump 69 -> 70 the
/// same night. The value now comes from the registry, so there is no next bump.
fn ordinary_top_level_union_fixture() -> IdentityRegistries {
    let mut identity = real_identity();
    let source =
        ORDINARY_UNION_FIXTURE_SOURCE.replace("@EPOCH@", &identity.fields_epoch.to_string());
    let table = registry_check::toml::parse(&source).expect("ordinary-union fixture parses");
    let (epoch, fields, ordinary_unions, reference_unions) =
        identity::fields_from(&table).expect("ordinary-union fixture models");

    // No literal to assert against: `epoch == identity.fields_epoch` holds by
    // construction, and the placeholder makes a lost substitution a parse error.
    assert!(fields.is_empty());
    assert!(reference_unions.is_empty());
    assert_eq!(ordinary_unions.len(), 1);
    let union = &ordinary_unions[0];
    assert_eq!(union.field_tag, None, "omitted field_tag means top-level");
    assert_eq!(union.arms.len(), 2);
    assert_eq!(union.arms[0].payload_kind, "unit");
    assert_eq!(union.arms[0].payload_sha256, None);
    assert_eq!(union.arms[1].payload_kind, "inline-record");
    assert_eq!(
        union.arms[1].payload_sha256.as_deref(),
        Some("0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef")
    );

    // An identity now, not an override -- kept so the fixture still states which
    // epoch its rows belong to, and so that a future deliberate divergence has
    // one obvious place to happen.
    identity.fields_epoch = epoch;
    // Keep the real ordinary unions so their anchor fields still resolve; the
    // synthetic fixture union stays at index 0 for the mutation tests.
    let mut all_unions = ordinary_unions;
    all_unions.append(&mut identity.ordinary_unions);
    identity.ordinary_unions = all_unions;
    // The index-0 claim in the comment above is load-bearing and was unchecked:
    // `wire_backed_top_level_union_fixture` and the embedded-union fixtures all
    // reach for `ordinary_unions[0]` by index, so a stitch-order change would
    // silently point every wire-backed test at a REAL union and they would go on
    // passing while testing the wrong object.
    assert_eq!(
        identity.ordinary_unions[0].union_name, "FixtureTopLevelUnion",
        "the synthetic union must stay at index 0; every fixture built on this one indexes it"
    );
    identity
}

fn codes_without_assignment_drift(r: &IdentityRegistries) -> Vec<String> {
    identity::validate_identity(r)
        .into_iter()
        .filter(|violation| violation.code != "registry_assignment_drift")
        .map(|violation| violation.code)
        .collect()
}

fn rename_logical_command_input_union(identity: &mut IdentityRegistries, name: &str) {
    let (containing_schema, field_tag) = {
        let union = identity
            .unions
            .iter_mut()
            .find(|union| {
                union.containing_schema == "LogicalCommandRecord" && union.field_tag == 0x0003
            })
            .expect("LogicalCommandRecord.command reference union exists");
        union.union_name = name.to_owned();
        for arm in &mut union.arms {
            arm.union_name = name.to_owned();
        }
        (union.containing_schema.clone(), union.field_tag)
    };
    identity
        .fields
        .iter_mut()
        .find(|field| field.containing_schema == containing_schema && field.field_tag == field_tag)
        .expect("LogicalCommandRecord.command anchor exists")
        .exact_wire_type = name.to_owned();
}

/// Reverse the cq4x capsule retarget so the pre-erratum durable-fields pin keeps
/// reconstructing from live rows.  `CommitMarker.capsule_ref` is a pre-erratum
/// field whose row was MODIFIED rather than added -- its `target_schema_id` moved
/// from the g0 scaffold `CommitCapsule` to the source-named `CommittedEffectCapsule`
/// (the plan spells `capsule_ref:StrongRef<CommittedEffectCapsule>` at 393/1912/1944
/// and never mentions `CommitCapsule`).  A modification is invisible to the
/// post-erratum row filters above, which only drop ADDED rows, so it has to be
/// undone here the same way the A01 wire-type flips are.
fn undo_cq4x_capsule_retarget(identity: &mut IdentityRegistries) {
    let field = identity
        .fields
        .iter_mut()
        .find(|field| {
            field.containing_schema == "CommitMarker" && field.stable_name == "capsule_ref"
        })
        .expect("CommitMarker.capsule_ref exists");
    field.target_schema_id = Some("CommitCapsule".to_owned());
}

/// Reverse mn8i's repairs to existing A12 rows for the historical witness.
///
/// The 80 added fields are removed by the historical cohort filter. These
/// modifications need explicit reversal because a filter cannot see the
/// previous CheckpointStateVector order or the previous top-level union shape.
fn undo_mn8i_exact_order_repairs(identity: &mut IdentityRegistries) {
    identity
        .fields
        .iter_mut()
        .find(|field| {
            field.containing_schema == "CheckpointStateVector"
                && field.stable_name == "mandatory_inventory"
        })
        .expect("CheckpointStateVector.mandatory_inventory exists")
        .construction_order = 35;

    // LocalConstraintReservationRecordState is NOT undone here.  It is itself a
    // post-erratum union (81ccbce), so the reconstruction removes it outright via
    // post_erratum_union; reversing its field_tag would be compensating for a row
    // that must not be present at all.

    for (union_name, allowed) in [
        ("ConstraintStateMutation", vec!["ConstraintStateMutation"]),
        ("QuotaPath", vec!["QuotaPath"]),
        (
            "TerminalAuditGate",
            vec!["KeyDestroyProposal", "SequenceNeutralSpec<Tag>"],
        ),
    ] {
        if let Some(union) = identity
            .ordinary_unions
            .iter_mut()
            .find(|union| union.union_name == union_name)
        {
            union.allowed_containing_schemas = allowed.into_iter().map(str::to_owned).collect();
        }
    }
}

/// Reverse the transcript-visible A01 increment-2B exactness repairs so the
/// pre-erratum durable-fields pin keeps reconstructing from live rows.  The
/// repair's bound corrections are transcript-invisible (field max_size_bytes
/// is not pinned) and need no undo; only the five wire-type flips and the two
/// ordinary-union tag/bound corrections appear in the assignment transcript.
fn undo_a01_exactness_repair(identity: &mut IdentityRegistries) {
    for field in &mut identity.fields {
        let flipped = matches!(
            (field.containing_schema.as_str(), field.stable_name.as_str()),
            (
                "RemoteReleaseSummaryEntry" | "RemoteRetentionReleaseAckCertificate",
                "grant_id"
            ) | (
                "RemoteReleaseSummaryEntry"
                    | "RemoteRetentionReleaseAckCertificate"
                    | "RemoteRetentionReleaseTombstone",
                "release_nonce"
            )
        );
        if flipped {
            field.exact_wire_type = "id256".to_owned();
        }
    }
    for union in &mut identity.ordinary_unions {
        if matches!(
            union.union_name.as_str(),
            "RootAuthorityTrustArtifactKind" | "TrustTransition"
        ) {
            union.tag_wire_type = "u16".to_owned();
            union.max_size_bytes = 16_777_216;
            for arm in &mut union.arms {
                arm.max_size_bytes = 16_777_216;
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Baseline.
