fn wire_backed_top_level_union_fixture() -> IdentityRegistries {
    let mut identity = ordinary_top_level_union_fixture();
    let union = &mut identity.ordinary_unions[0];
    union.union_name = "FixtureWireBackedUnion".into();
    union.containing_schema = "FixtureWireBackedUnion".into();
    union.union_path = "FixtureWireBackedUnion".into();
    union.role_predicate = "role-local || role-meta".into();
    for arm in &mut union.arms {
        arm.union_name = "FixtureWireBackedUnion".into();
        arm.containing_schema = "FixtureWireBackedUnion".into();
        arm.union_path = "FixtureWireBackedUnion".into();
        arm.role_predicate = "role-local || role-meta".into();
    }
    let variants: Vec<_> = union
        .arms
        .iter()
        .enumerate()
        .map(|(index, arm)| WireType {
            wire_type_id: 0x7ff1 + i64::try_from(index).expect("fixture index fits i64"),
            name: format!("{}.{}", union.union_name, arm.stable_name),
            kind: "union_variant".into(),
            status: arm.version_status.clone(),
            containing_union: Some(union.union_name.clone()),
            wire_tag: Some(arm.arm_tag),
            encoding_context: arm.payload_kind.clone(),
            allowed_containing_schemas: vec![union.union_name.clone()],
            max_size_bytes: arm.max_size_bytes,
        })
        .collect();
    identity.wire.push(WireType {
        wire_type_id: 0x7ff0,
        name: union.union_name.clone(),
        kind: "union".into(),
        status: union.version_status.clone(),
        containing_union: None,
        wire_tag: None,
        encoding_context: union.encoding_context.clone(),
        allowed_containing_schemas: union.allowed_containing_schemas.clone(),
        max_size_bytes: union.max_size_bytes,
    });
    identity.wire.extend(variants);
    identity
}

#[test]
fn idr_wire_backed_top_level_union_requires_exact_cross_index() {
    let identity = wire_backed_top_level_union_fixture();
    assert!(
        codes_without_assignment_drift(&identity).is_empty(),
        "a top-level ordinary union must cross-index one exact wire parent and variant set"
    );

    let mut wrong_path = identity.clone();
    wrong_path.ordinary_unions[0].union_path = "wrong_path".into();
    for arm in &mut wrong_path.ordinary_unions[0].arms {
        arm.union_path = "wrong_path".into();
    }
    assert!(
        codes_without_assignment_drift(&wrong_path)
            .contains(&"ordinary_union_name_collision".to_owned()),
        "partial name equality must not acquire the top-level wire exception"
    );

    let mut embedded = identity.clone();
    embedded.ordinary_unions[0].field_tag = Some(1);
    let codes = codes_without_assignment_drift(&embedded);
    assert!(
        codes.contains(&"ordinary_union_name_collision".to_owned())
            && codes.contains(&"ordinary_union_field_mismatch".to_owned()),
        "a field tag removes the top-level wire exception and requires an exact anchor: {codes:?}"
    );

    let mut missing_variant = identity.clone();
    missing_variant.wire.pop().expect("fixture wire variant");
    assert!(
        codes_without_assignment_drift(&missing_variant)
            .contains(&"ordinary_union_wire_contract_mismatch".to_owned()),
        "a missing wire variant escaped the exact cross-index"
    );

    let mut discriminant_with_payload = identity.clone();
    discriminant_with_payload
        .wire
        .iter_mut()
        .find(|wire| wire.name == "FixtureWireBackedUnion")
        .expect("fixture wire parent")
        .kind = "discriminant".into();
    assert!(
        codes_without_assignment_drift(&discriminant_with_payload)
            .contains(&"ordinary_union_wire_contract_mismatch".to_owned()),
        "a discriminant parent accepted an inline-record arm"
    );

    let mut wrong_tag = identity;
    wrong_tag
        .wire
        .iter_mut()
        .find(|wire| wire.containing_union.as_deref() == Some("FixtureWireBackedUnion"))
        .expect("fixture wire variant")
        .wire_tag = Some(3);
    assert!(
        codes_without_assignment_drift(&wrong_tag)
            .contains(&"ordinary_union_wire_contract_mismatch".to_owned()),
        "wire/ordinary tag drift escaped the exact cross-index"
    );
}

#[test]
fn idr_wire_backed_top_level_union_rejects_container_scope_drift() {
    let identity = wire_backed_top_level_union_fixture();
    let parent_name = identity.ordinary_unions[0].union_name.clone();

    let mut wildcard_parent = identity.clone();
    wildcard_parent
        .wire
        .iter_mut()
        .find(|wire| wire.name == parent_name)
        .expect("fixture wire parent")
        .allowed_containing_schemas = vec!["*".into()];
    assert!(
        codes_without_assignment_drift(&wildcard_parent)
            .contains(&"ordinary_union_wire_contract_mismatch".to_owned()),
        "a wildcard wire-parent scope escaped the exact ordinary-union cross-index"
    );

    let mut wildcard_union = identity.clone();
    wildcard_union.ordinary_unions[0].allowed_containing_schemas = vec!["*".into()];
    assert!(
        codes_without_assignment_drift(&wildcard_union)
            .contains(&"ordinary_union_container_contract_mismatch".to_owned()),
        "a wildcard ordinary-union scope escaped the concrete-container contract"
    );

    let mut extra_parent = identity.clone();
    extra_parent
        .wire
        .iter_mut()
        .find(|wire| wire.name == parent_name)
        .expect("fixture wire parent")
        .allowed_containing_schemas
        .push("RootSlot".into());
    assert!(
        codes_without_assignment_drift(&extra_parent)
            .contains(&"ordinary_union_wire_contract_mismatch".to_owned()),
        "an extra wire-parent container escaped the exact ordinary-union cross-index"
    );

    let mut missing_parent = identity;
    missing_parent
        .wire
        .iter_mut()
        .find(|wire| wire.name == parent_name)
        .expect("fixture wire parent")
        .allowed_containing_schemas
        .clear();
    let codes = codes_without_assignment_drift(&missing_parent);
    assert!(
        codes.contains(&"ordinary_union_wire_contract_mismatch".to_owned())
            && codes.contains(&"bad_field".to_owned()),
        "a missing wire-parent container escaped the closed contract: {codes:?}"
    );
}

#[test]
fn idr_allowed_containing_schema_resolution_accepts_candidate_or_stronger_and_rejects_unknown() {
    let mut identity = real_identity();
    for wire in &mut identity.wire {
        wire.allowed_containing_schemas = vec!["*".to_owned()];
    }
    for union in &mut identity.ordinary_unions {
        union.allowed_containing_schemas = vec![union.union_name.clone()];
    }

    identity.wire[0].allowed_containing_schemas = vec!["CandidateOnly<Local>".to_owned()];
    identity.ordinary_unions[0].allowed_containing_schemas = vec!["CandidateOnly<Meta>".to_owned()];

    let accepted =
        identity::validate_allowed_containing_schema_resolution(&identity, ["CandidateOnly"]);
    assert!(
        accepted.is_empty(),
        "one candidate backing must cover every generic specialization: {accepted:?}"
    );

    let rejected =
        identity::validate_allowed_containing_schema_resolution(&identity, std::iter::empty());
    assert_eq!(
        rejected
            .iter()
            .filter(|violation| violation.code == "allowed_containing_schema_unresolved")
            .count(),
        2,
        "the same unbacked family must be rejected at both wire and ordinary-union citations: {rejected:?}"
    );
    assert!(
        rejected
            .iter()
            .any(|violation| violation.registry == "wire_types")
            && rejected
                .iter()
                .any(|violation| violation.registry == "durable_fields"),
        "one-law-two-artifacts coverage must include both projection surfaces: {rejected:?}"
    );
}

#[test]
fn idr_allowed_containing_schema_catalog_domain_is_nonempty_and_fail_closed() {
    let mut catalog = real_appendix_catalog();
    let concrete_wire_citations = catalog
        .identity
        .wire
        .iter()
        .flat_map(|row| &row.allowed_containing_schemas)
        .filter(|schema| !schema.as_str().eq("*"))
        .count();
    let ordinary_union_citations = catalog
        .identity
        .ordinary_unions
        .iter()
        .map(|row| row.allowed_containing_schemas.len())
        .sum::<usize>();
    assert_eq!(
        (concrete_wire_citations, ordinary_union_citations),
        // 603 -> 604 (fgdb-a20-restore-promotion-ivsp): the Meta completion
        // precondition constrains its generated discriminant to the one exact host.
        // 604 -> 610 / 430 -> 436 (fgdb-a20-restore-promotion-ivsp): the
        // TerminalAuditGate closure names its six Spec-family consumers in
        // both generated artifacts.
        // 610 -> 615 (fgdb-ge6a): the five Tier-D record wire types each name
        // their one exact host (DescriptorKey/SortedIdentityColumn/
        // VisibilitySpan -> DeltaBlockVersion, PropertyEntry -> VertexRowPatch,
        // PropertyEntryList -> EdgePropertyPatch); id128 is wildcard and adds
        // no citation.
        // 615 -> 616 / 436 -> 437 (fgdb-a20-restore-promotion-ivsp): the
        // WeakAuthorityAppliedIdentity closure names RestoreShardOperationalAck
        // as a consumer in both generated artifacts (the applied-identity
        // ruling).
        // 616 -> 617 (fgdb-a20-restore-promotion-ivsp): the receipt's
        // tag-refined posture discriminant names its one exact host; the two
        // shared record mints are wildcard and add no citation.
        // 617 -> 621 (fgdb-ad4m): the LogicalEffectClass parent plus its
        // three exact variants each name their one closed containing schema.
        // 621 -> 625 (fgdb-rqw4): the three pending-reopen precondition
        // discriminants and the receipt's one-arm state discriminant each
        // name their one exact host.
        // 437 -> 439 (fgdb-5ekk): each generated family union names its own
        // wrapper as the single concrete containing schema (self-rooted
        // closure; no external embedder exists).
        (625, 439),
    );

    let baseline = appendix_a::validate_catalog(&catalog);
    assert!(
        !baseline.iter().any(|violation| {
            violation.code == "projection_allowed_containing_schema_unresolved"
        }),
        "the repaired catalog must close every concrete consumer citation: {baseline:?}"
    );

    let projected_names = catalog
        .identity
        .logical
        .iter()
        .map(|row| row.name.as_str())
        .chain(
            catalog
                .identity
                .physical
                .iter()
                .map(|row| row.name.as_str()),
        )
        .chain(
            catalog
                .identity
                .bootstrap
                .iter()
                .map(|row| row.name.as_str()),
        )
        .chain(
            catalog
                .identity
                .prebootstrap
                .iter()
                .map(|row| row.name.as_str()),
        )
        .chain(catalog.identity.wire.iter().map(|row| row.name.as_str()))
        .collect::<BTreeSet<_>>();
    assert!(
        catalog
            .top_level_candidates
            .iter()
            .any(|row| { row.symbol == "KeyWrap" && row.source_kind.eq("confirmed") })
            && !projected_names.contains("KeyWrap")
            && !catalog
                .reservations
                .iter()
                .any(|row| row.symbol == "KeyWrap"),
        "KeyWrap must exercise confirmed-candidate-only admission"
    );
    assert!(
        catalog
            .reservations
            .iter()
            .any(|row| row.symbol == "ExternalKeyDestructionOperationRecord")
            && !projected_names.contains("ExternalKeyDestructionOperationRecord")
            && !catalog.top_level_candidates.iter().any(|row| {
                row.symbol == "ExternalKeyDestructionOperationRecord"
                    && row.source_kind.eq("confirmed")
            }),
        "ExternalKeyDestructionOperationRecord must exercise reservation-only admission"
    );

    catalog
        .identity
        .wire
        .iter_mut()
        .find(|row| row.name.eq("StrongRef"))
        .expect("StrongRef wire row exists")
        .allowed_containing_schemas = vec!["ZzFabricatedSchema".to_owned()];
    let violations = appendix_a::validate_catalog(&catalog);
    assert!(
        violations.iter().any(|violation| {
            violation.code == "projection_allowed_containing_schema_unresolved"
                && violation.row_id == "wire_types::StrongRef"
                && violation.msg.contains("ZzFabricatedSchema")
        }),
        "the Appendix A integration must reject an unbacked concrete citation: {violations:?}"
    );
}

#[test]
fn idr_time_issuance_freeze_backing_and_lifecycle_consumer_are_source_exact() {
    const TIME_FREEZE: &str = "TimeIssuanceAdmissionFreezeSpec";
    const LIFECYCLE: &str = "LifecycleScaffoldingNotRequired";
    const FIELD_MARKER: &str = "terminal_audit_gate:LifecycleScaffoldingNotRequired";

    let catalog = real_appendix_catalog();
    let source = real_plan_source();
    let appendix = source_range(
        &source,
        catalog.source_manifest.start_line,
        catalog.source_manifest.end_line,
    );
    let specs = catalog
        .slices
        .iter()
        .map(|slice| appendix_source::SourceSliceSpec {
            id: &slice.id,
            start_line: usize::try_from(slice.start_line).expect("slice start fits"),
            end_line: usize::try_from(slice.end_line).expect("slice end fits"),
        })
        .collect::<Vec<_>>();
    let census = appendix_source::census_appendix_source(
        &appendix,
        usize::try_from(catalog.source_manifest.start_line).expect("source start fits"),
        &specs,
    )
    .expect("source census");

    let expected_consumers = vec![
        "AuditSigningAttemptSupersedeSpec".to_owned(),
        "AuditTerminalFreezeSpec".to_owned(),
        "AuditTerminalPlanAbandonSpec".to_owned(),
        "CertificateAttemptAbandonSpec".to_owned(),
        "GlobalAttemptRegistrationSpec".to_owned(),
        "GlobalBeginReservationSpec".to_owned(),
        "GlobalFinalCertificationReserveSpec".to_owned(),
        "GlobalPrepareAdmissionSpec".to_owned(),
        "GlobalStatementRegistrationSpec".to_owned(),
        "LocalAttemptRegistrationSpec".to_owned(),
        "LocalBeginReservationSpec".to_owned(),
        "LocalFinalCertificationReserveSpec".to_owned(),
        "LocalPrepareAdmissionSpec".to_owned(),
        "LocalStatementRegistrationSpec".to_owned(),
        TIME_FREEZE.to_owned(),
    ];
    let expected_parser_consumers = expected_consumers
        .iter()
        .filter(|name| !name.as_str().eq("LocalAttemptRegistrationSpec"))
        .cloned()
        .collect::<BTreeSet<_>>();
    let lifecycle_fields = census
        .fields
        .iter()
        .filter(|field| field.exact_types.iter().any(|exact| exact.eq(LIFECYCLE)))
        .collect::<Vec<_>>();
    assert_eq!(
        lifecycle_fields.len(),
        16,
        "the structural census must retain all directly parsed lifecycle-gate occurrences"
    );
    assert_eq!(
        lifecycle_fields
            .iter()
            .map(|field| field.key.schema_family.clone())
            .collect::<BTreeSet<_>>(),
        expected_parser_consumers,
        "the directly parsed lifecycle-gate consumer families must remain source exact"
    );
    assert!(
        lifecycle_fields.iter().any(|field| {
            field.key.schema_family.eq(TIME_FREEZE)
                && field.key.stable_name.eq("terminal_audit_gate")
                && field.exact_types.iter().map(String::as_str).eq([LIFECYCLE])
        }),
        "the A16 freeze source must type its terminal_audit_gate exactly"
    );
    let mut freeze_fields = census
        .fields
        .iter()
        .filter(|field| field.key.schema_family.eq(TIME_FREEZE))
        .collect::<Vec<_>>();
    freeze_fields.sort_by_key(|field| {
        field
            .locations
            .first()
            .map(|location| (location.start.line, location.start.column))
            .expect("every source field has a location")
    });
    assert_eq!(
        freeze_fields
            .iter()
            .map(|field| field.key.stable_name.as_str())
            .collect::<Vec<_>>(),
        [
            "transition_id",
            "retiring_profile_oid",
            "expected_active_projection",
            "freeze_generation",
            "expected_reservation_index_ref",
            "terminal_audit_gate",
        ],
        "the A16 freeze field order must remain exactly source ordered"
    );
    assert!(
        freeze_fields
            .iter()
            .all(|field| field.key.schema_owner.eq(TIME_FREEZE)),
        "every A16 freeze field must retain its granular source owner"
    );
    assert!(
        freeze_fields[..5]
            .iter()
            .all(|field| field.ambiguous && field.exact_types.is_empty()),
        "the five shorthand field types must remain explicitly ambiguous rather than fabricated"
    );

    let appendix_text = std::str::from_utf8(&appendix).expect("Appendix A is UTF-8");
    assert_eq!(
        appendix_text.matches(FIELD_MARKER).count(),
        17,
        "the exact lifecycle-gate field spelling must occur 17 times in Appendix A"
    );
    for consumer in &expected_consumers {
        assert!(
            appendix_text
                .lines()
                .any(|line| line.contains(FIELD_MARKER) && line.contains(consumer)),
            "source lacks the lifecycle-gate occurrence attributed to {consumer}"
        );
    }
    assert!(
        !appendix_text.contains("TimeIssuanceAdmissionFreezeSpecFabricated"),
        "the source control name must remain absent"
    );

    let freeze_wire = catalog
        .identity
        .wire
        .iter()
        .find(|row| row.name.eq(TIME_FREEZE))
        .expect("A16 freeze wire backing exists");
    assert_eq!(freeze_wire.wire_type_id, 0x0569);
    assert_eq!(freeze_wire.kind, "record");
    assert_eq!(freeze_wire.status, "reserved");
    assert_eq!(
        freeze_wire.allowed_containing_schemas,
        [TIME_FREEZE.to_owned()]
    );
    assert!(catalog.targets.iter().any(|target| {
        target.source_key.eq("top|TimeIssuanceAdmissionFreezeSpec")
            && target
                .target_row_id
                .eq("a16:wire-type:time-issuance-admission-freeze-spec")
            && target.target_kind.eq("wire-type")
            && target.definition_status.eq("declared")
    }));
    assert!(catalog.top_level_candidates.iter().any(|candidate| {
        candidate.symbol.eq(TIME_FREEZE)
            && candidate.source_kind.eq("ambiguous")
            && candidate.identity_class.eq("wire")
    }));

    let lifecycle_wire = catalog
        .identity
        .wire
        .iter()
        .find(|row| row.name.eq(LIFECYCLE))
        .expect("lifecycle-scaffolding wire row exists");
    assert_eq!(
        lifecycle_wire.allowed_containing_schemas, expected_consumers,
        "the lifecycle-scaffolding consumer closure must equal the source census"
    );

    let mut fabricated = catalog;
    fabricated
        .identity
        .wire
        .iter_mut()
        .find(|row| row.name.eq(LIFECYCLE))
        .expect("lifecycle-scaffolding wire row exists")
        .allowed_containing_schemas
        .iter_mut()
        .find(|schema| schema.as_str().eq(TIME_FREEZE))
        .expect("A16 consumer citation exists")
        .push_str("Fabricated");
    let violations = appendix_a::validate_catalog(&fabricated);
    assert!(
        violations.iter().any(|violation| {
            violation
                .code
                .eq("projection_allowed_containing_schema_unresolved")
                && violation
                    .row_id
                    .eq("wire_types::LifecycleScaffoldingNotRequired")
                && violation
                    .msg
                    .contains("TimeIssuanceAdmissionFreezeSpecFabricated")
        }),
        "a fabricated replacement consumer must fail closed: {violations:?}"
    );
}

