#[test]
fn idr_a21_silent_resolution_unions_are_wire_envelopes() {
    let r = real_identity();
    let catalog = real_appendix_catalog();
    let expected = [
        (
            "ThroughInstalledSuccessorAcknowledgedOrSubjectTerminal",
            0x0541,
            &[
                (0x0001, "0x0001 ConsumerTerminalWithoutSuccessor", 0x0542),
                (0x0002, "0x0002 InstalledSuccessorAcknowledged", 0x0543),
                (0x0003, "0x0003 SubjectTerminal", 0x0544),
            ][..],
        ),
        (
            "ThroughCapabilityMigrationIndexTerminal",
            0x0545,
            &[
                (
                    0x0001,
                    "0x0001 ConsumerTerminalWithoutIndexSelection",
                    0x0546,
                ),
                (0x0002, "0x0002 LiveSuccessorEntrySelected", 0x0547),
            ][..],
        ),
        (
            "AuditReceiptValidationResolution",
            0x0548,
            &[
                (0x0001, "0x0001 LocalTerminalReceiptIndex", 0x0549),
                (0x0002, "0x0002 MetaTerminalReceiptIndex", 0x054a),
                (0x0003, "0x0003 LocalFrameCompleted", 0x054b),
                (0x0004, "0x0004 MetaFrameCompleted", 0x054c),
                (0x0005, "0x0005 LocalCancelledBeforeWrite", 0x054d),
                (0x0006, "0x0006 MetaCancelledBeforeWrite", 0x054e),
            ][..],
        ),
    ];
    for (name, parent_code, expected_arms) in expected {
        let parent = r
            .wire
            .iter()
            .find(|row| row.name == name)
            .unwrap_or_else(|| panic!("missing ruled a21 wire union {name}"));
        assert_eq!(parent.wire_type_id, parent_code, "{name} code drift");
        assert_eq!(parent.kind, "union", "{name} must remain a wire union");
        assert_eq!(parent.status, "reserved");
        assert_eq!(
            parent.allowed_containing_schemas,
            [name],
            "{name} must keep its exact self-only closure"
        );
        assert!(
            r.logical.iter().all(|row| row.name != name),
            "{name} must not spend a logical object-kind code"
        );
        assert!(
            catalog.reservations.iter().all(|row| row.symbol != name),
            "{name} is not a StrongRef family and must not gain a reservation"
        );

        let union = r
            .ordinary_unions
            .iter()
            .find(|row| row.union_name == name)
            .unwrap_or_else(|| panic!("missing ruled a21 ordinary union {name}"));
        assert_eq!(union.containing_schema, name);
        assert_eq!(union.union_path, name);
        assert_eq!(union.tag_wire_type, "u16");
        assert_eq!(union.allowed_containing_schemas, [name]);
        assert_eq!(union.arms.len(), expected_arms.len());
        for &(arm_tag, source_arm_name, variant_code) in expected_arms {
            let arm = union
                .arms
                .iter()
                .find(|row| row.arm_tag == arm_tag)
                .unwrap_or_else(|| panic!("missing ruled a21 arm {name} tag {arm_tag:#06x}"));
            assert_eq!(arm.source_arm_name, source_arm_name);
            let variant_name = format!("{name}.{}", arm.stable_name);
            let variant = r
                .wire
                .iter()
                .find(|row| row.name == variant_name)
                .unwrap_or_else(|| panic!("missing ruled a21 wire variant {variant_name}"));
            assert_eq!(
                variant.wire_type_id, variant_code,
                "{variant_name} code drift"
            );
            assert_eq!(variant.kind, "union_variant");
            assert_eq!(variant.containing_union.as_deref(), Some(name));
            assert_eq!(variant.wire_tag, Some(arm_tag));
            assert_eq!(variant.allowed_containing_schemas, [name]);
        }
    }
}

/// A tag-refined wrapper's refinement claim must resolve to a registered arm
/// (fgdb-gpms).
///
/// Appendix A a20:2593 mints two tag-refined strong references and states the
/// rule they serve — "variant syntax is never used as a reference target" — so
/// the refinement, not the target schema, is what makes the wrapper different
/// from a plain `StrongRef`. `OperationalRestoreTerminalPinBasisRef` is the
/// difference between "a pin basis" and "an *Operational* pin basis"; a decoder
/// that admits the `Abandoned` arm through it accepts a state the source
/// rejects.
///
/// MEASURED 2026-07-27 at dbaab71, before this law: 6 rows carry a refinement
/// claim and NOTHING read it. `encoding_context` was checked for non-emptiness
/// and nothing else, so a claim naming a nonexistent arm, or a real arm under
/// the wrong `arm_tag`, read exactly like a correct one.
///
/// The completeness half is not decoration. 2 of those 6 were written in a
/// prose dialect ("the Sharded/ExternalCas RestoreServicePromotionManifest
/// arm" — no tag, no union clause) which parses to `None`; a law that only
/// validated what it could parse would have skipped precisely the rows that
/// motivated it. Case (d) below is that control, and it fails on the
/// pre-change spelling of a landed row.
#[test]
fn idr_refinement_claims_resolve_to_a_registered_arm() {
    let base = real_identity();
    let base_codes = codes_without_assignment_drift(&base);
    for code in [
        "refinement_claim_unparseable",
        "refinement_conjunction_invalid",
        "refinement_union_unresolved",
        "refinement_arm_unresolved",
        "refinement_arm_tag_mismatch",
    ] {
        assert!(
            !base_codes.contains(&code.to_string()),
            "the landed corpus must already satisfy the refinement law, but {code} fires: \
             {base_codes:?}"
        );
    }

    // NON-VACUITY. The law is an implication over rows that make a claim; if no
    // row makes one, every assertion above is vacuously true. Pin the domain.
    let claimants: BTreeSet<&str> = base
        .wire
        .iter()
        .filter(|w| {
            w.encoding_context
                .contains(identity::REFINEMENT_CLAIM_MARKER)
                || w.encoding_context
                    .contains(identity::REFINEMENT_CONJUNCTION_MARKER)
        })
        .map(|w| w.name.as_str())
        .collect();
    // 6 -> 7 (fgdb-a20-restore-promotion-ivsp): PromotedAwaitingReopenLocalRestorePhase,
    // wire 0x0559. It is the FIRST claimant that is not a reference_wrapper — the
    // fgdb-gpms ruling extends the tag-refined instrument from the reference position
    // to the value position, so a `kind = "discriminant"` row now carries a refinement
    // claim and this law's domain covers it on exactly the same terms.
    // 7 -> 8 (fgdb-5uj5): LocalAbortFinalCertificationSelection, wire 0x0562,
    // applies that same law to AdmittedTxnAbortCommand.required_selection.
    // 8 -> 9 (fgdb-a20-restore-promotion-ivsp):
    // PromotedAwaitingReopenMetaRestorePhase, wire 0x056a, applies the existing
    // MetaRestorePhase arm at 0x0003 to the completion precondition.
    // 9 -> 12 (fgdb-rqw4): the three pending-reopen precondition discriminants
    // (wires 0x0578/0x0579/0x057a) each claim the OperationalPendingIndependentReopen
    // bootstrap-phase arm at 0x0004 — singleton claims only; the ::Sealed conjunct
    // stays prose by ruling, so conjunction_claimants below must stay empty.
    assert_eq!(
        claimants.len(),
        12,
        "refinement-claim population moved; a new tag-refined wrapper must be added here \
         deliberately, not discovered by a green run: {claimants:?}"
    );
    let conjunction_claimants: BTreeSet<&str> = base
        .wire
        .iter()
        .filter(|w| {
            w.encoding_context
                .contains(identity::REFINEMENT_CONJUNCTION_MARKER)
        })
        .map(|w| w.name.as_str())
        .collect();
    assert_eq!(conjunction_claimants, BTreeSet::new()); // ubs:ignore -- test census intentionally panics.

    // The subject: a landed wrapper whose claim is already in the grammar.
    let subject = |r: &IdentityRegistries| -> usize {
        r.wire
            .iter()
            .position(|w| w.name == "OperationalRestoreTerminalPinBasisRef")
            .expect("the landed a18 tag-refined wrapper")
    };
    let canonical = "generated tag-refined strong reference whose validator admits only the Operational arm \
         (arm_tag 0x0001) of the RestoreTerminalPinBasis<Role> union";
    assert!(
        base.wire[subject(&base)]
            .encoding_context
            .starts_with(canonical),
        "subject claim spelling moved: {:?}",
        base.wire[subject(&base)].encoding_context
    );

    // (a) right arm, wrong tag -- the silent-drift case. Both `Operational` and
    // `Abandoned` are real arms of this union, so the arm name alone cannot
    // catch a tag swapped to its sibling.
    let mut wrong_tag = real_identity();
    let i = subject(&wrong_tag);
    wrong_tag.wire[i].encoding_context = wrong_tag.wire[i]
        .encoding_context
        .replace("(arm_tag 0x0001)", "(arm_tag 0x0002)");
    assert!(
        codes(&wrong_tag).contains(&"refinement_arm_tag_mismatch".to_string()),
        "a refinement may not name an arm under a tag the arm does not carry"
    );

    // (b) the union itself is not registered.
    let mut no_union = real_identity();
    let i = subject(&no_union);
    no_union.wire[i].encoding_context = no_union.wire[i]
        .encoding_context
        .replace("RestoreTerminalPinBasis<Role> union", "NoSuchUnion union");
    assert!(
        codes(&no_union).contains(&"refinement_union_unresolved".to_string()),
        "a wrapper may not refine an unregistered union"
    );

    // (c) the arm is not registered. This is the case that blocks the value-side
    // extension of the instrument: fgdb-gpms measures 137 of 190 state-value
    // field candidates whose referent arm has no [[union_arm]] row, and each
    // would mint exactly this shape.
    let mut no_arm = real_identity();
    let i = subject(&no_arm);
    no_arm.wire[i].encoding_context = no_arm.wire[i]
        .encoding_context
        .replace("the Operational arm", "the Operationall arm");
    assert!(
        codes(&no_arm).contains(&"refinement_arm_unresolved".to_string()),
        "a wrapper may not refine an arm that is not registered"
    );

    // (d) COMPLETENESS. The pre-change spelling of a different landed row --
    // a real claim, in prose, with no machine-readable referent.
    let mut prose = real_identity();
    let j = prose
        .wire
        .iter()
        .position(|w| w.name == "ExternalCasRestoreServicePromotionReceiptRef")
        .expect("the landed a20 wrapper canonicalized by fgdb-gpms");
    prose.wire[j].encoding_context =
        "generated tag-refined strong reference whose validator admits only the \
         ExternalCasCataloged RestoreServicePromotionReceipt arm (a20:2593)"
            .into();
    assert!(
        codes(&prose).contains(&"refinement_claim_unparseable".to_string()),
        "a refinement stated only in prose is unenforceable and must not pass"
    );

    // CONFORMANT CONTROL. Re-point the same row at the union's OTHER real arm
    // at that arm's real tag. This is a different refinement, and a wrong one
    // for this wrapper, but it is well-formed -- so it must stay green. Without
    // it, cases (a)-(d) are consistent with a law that rejects every edit.
    let mut ok = real_identity();
    let i = subject(&ok);
    ok.wire[i].encoding_context = ok.wire[i].encoding_context.replace(
        "the Operational arm (arm_tag 0x0001)",
        "the Abandoned arm (arm_tag 0x0002)",
    );
    assert!(
        ok.wire[i]
            .encoding_context
            .contains("the Abandoned arm (arm_tag 0x0002)"),
        "conformant control did not apply"
    );
    let ok_codes = codes_without_assignment_drift(&ok);
    for code in [
        "refinement_claim_unparseable",
        "refinement_conjunction_invalid",
        "refinement_union_unresolved",
        "refinement_arm_unresolved",
        "refinement_arm_tag_mismatch",
    ] {
        assert!(
            !ok_codes.contains(&code.to_string()),
            "conformant control must stay green, but {code} fires"
        );
    }
}

/// A two-location refinement is one atomic claim, not two independently green
/// facts (fgdb-refinement-claim-grammar-cannot-conjoin-78tr).
#[test]
fn idr_refinement_conjunction_is_atomic_and_total() {
    let with_context = |context: &str| {
        let mut identity = real_identity();
        let found = identity
            .wire
            .iter_mut()
            // ubs:ignore -- public registry symbol, not secret-bearing data.
            .find(|w| w.name == "OperationalRestoreTerminalPinBasisRef")
            .map(|row| row.encoding_context = context.to_owned())
            .is_some();
        (found, identity)
    };
    let refinement_codes = |(found, identity): &(bool, IdentityRegistries)| -> BTreeSet<String> {
        if !found {
            return BTreeSet::from(["fixture_subject_missing".to_owned()]);
        }
        codes_without_assignment_drift(identity)
            .into_iter()
            .filter(|code| code.starts_with("refinement_"))
            .collect()
    };
    let assert_refinement_codes = |label: &str,
                                   fixture: (bool, IdentityRegistries),
                                   expected: &[&str]| {
        let expected: BTreeSet<String> = expected.iter().map(|code| (*code).to_owned()).collect();
        let actual = refinement_codes(&fixture);
        assert_eq!(actual, expected, "{label}"); // ubs:ignore -- test witness intentionally panics.
    };

    // Both clauses name independently registered, live locations. The exact
    // combination is a parser/validator fixture, not a semantic claim about
    // this wrapper; the existing singleton suite uses its other-arm control on
    // the same terms.
    let canonical = "generated conjunctive refinement whose validator admits only when both the \
        Operational arm (arm_tag 0x0001) of the RestoreTerminalPinBasis<Role> union and the \
        Sharded arm (arm_tag 0x0002) of the RestoreServicePromotionManifestTargetPosture union";
    assert_refinement_codes("valid conjunction", with_context(canonical), &[]);

    // TOTALITY: corrupt only the SECOND clause. A parser that checked the first
    // clause and stopped would stay green on all three mutations.
    assert_refinement_codes(
        "second arm resolves",
        with_context(&canonical.replace("the Sharded arm", "the Shardedd arm")),
        &["refinement_arm_unresolved"],
    );
    assert_refinement_codes(
        "second arm tag resolves",
        with_context(&canonical.replace(
            "Sharded arm (arm_tag 0x0002)",
            "Sharded arm (arm_tag 0x0001)",
        )),
        &["refinement_arm_tag_mismatch"],
    );
    assert_refinement_codes(
        "second union resolves",
        with_context(&canonical.replace(
            "RestoreServicePromotionManifestTargetPosture union",
            "NoSuchUnion union",
        )),
        &["refinement_union_unresolved"],
    );

    // ATOMICITY: missing, duplicate, third, and mixed clauses all advertise a
    // conjunction they do not actually encode, so they own one dedicated
    // diagnostic instead of falling back to a valid singleton.
    assert_refinement_codes(
        "missing second clause",
        with_context(&canonical.replace(
            " and the Sharded arm (arm_tag 0x0002) of the \
             RestoreServicePromotionManifestTargetPosture union",
            "",
        )),
        &["refinement_conjunction_invalid"],
    );
    assert_refinement_codes(
        "duplicate clause",
        with_context(&canonical.replace(
            "Sharded arm (arm_tag 0x0002) of the RestoreServicePromotionManifestTargetPosture union",
            "Operational arm (arm_tag 0x0001) of the RestoreTerminalPinBasis<Role> union",
        )),
        &["refinement_conjunction_invalid"],
    );
    assert_refinement_codes(
        "third clause",
        with_context(&format!(
            "{canonical} and the ExternalCasCataloged arm (arm_tag 0x0001) of the \
             RestoreServicePromotionReceipt union"
        )),
        &["refinement_conjunction_invalid"],
    );
    assert_refinement_codes(
        "mixed dialect",
        with_context(&format!(
            "{canonical}; independently admits only the Operational arm (arm_tag 0x0001) of the \
             RestoreTerminalPinBasis<Role> union"
        )),
        &["refinement_conjunction_invalid"],
    );

    // Two singleton markers are not an alternate spelling of conjunction.
    assert_refinement_codes(
        "two singleton markers",
        with_context(
            "generated split refinement whose validator admits only the Operational arm \
             (arm_tag 0x0001) of the RestoreTerminalPinBasis<Role> union and independently admits \
             only the Sharded arm (arm_tag 0x0002) of the \
             RestoreServicePromotionManifestTargetPosture union",
        ),
        &["refinement_claim_unparseable"],
    );
}

/// Generic restore contracts whose selected arm depends on `Role` expand to
/// concrete, role-erased projections rather than a conjunction (fgdb-ap4t).
///
/// The a18 source is bounded by `AuthorityOwningRole`, whose exact set is
/// Local|Meta and whose two `AwaitingSourceRelease` arms carry DIFFERENT tags.
/// The a19 generated reference family has Local|Meta|Shard validators with
/// structurally different registered locations.  One concrete value can never
/// inhabit every role at once, and serializing another role discriminator
/// would invent bytes absent from the source schema.
#[test]
fn idr_role_selected_restore_projections_are_exact_and_role_erased() {
    const ROLE_CODES: [&str; 8] = [
        "role_projection_claim_unparseable",
        "role_projection_source_unapproved",
        "role_projection_contract_mismatch",
        "role_projection_role_out_of_bound",
        "role_projection_role_missing",
        "role_projection_role_duplicate",
        "role_projection_branch_mismatch",
        "role_projection_refinement_syntax_forbidden",
    ];
    let role_codes = |identity: &IdentityRegistries| -> BTreeSet<String> {
        codes_without_assignment_drift(identity)
            .into_iter()
            .filter(|code| ROLE_CODES.contains(&code.as_str()))
            .collect()
    };
    let replace_context = |identity: &mut IdentityRegistries, name: &str, from: &str, to: &str| {
        let row = identity
            .wire
            .iter_mut()
            .find(|row| row.name == name) // ubs:ignore -- public registry-row name equality in a mutation fixture.
            .expect("role projection fixture subject is landed");
        assert!(row.encoding_context.contains(from), "fixture did not apply");
        row.encoding_context = row.encoding_context.replace(from, to);
    };

    let base = real_identity();
    assert_eq!(
        role_codes(&base),
        BTreeSet::new(), // ubs:ignore -- test witness intentionally panics.
        "the released role projections must satisfy their exact bijection"
    );
    let projection_names: BTreeSet<&str> = base
        .wire
        .iter()
        .filter(|row| {
            row.encoding_context
                .contains(identity::ROLE_PROJECTION_CLAIM_MARKER)
        })
        .map(|row| row.name.as_str())
        .collect();
    assert_eq!(
        projection_names,
        BTreeSet::from([
            "AwaitingSourceReleaseLocalRestorePhase",
            "AwaitingSourceReleaseMetaRestorePhase",
            "LocalInitialRestoreRegistryRef",
            "MetaInitialRestoreRegistryRef",
            "ShardInitialRestoreRegistryRef",
        ]),
        "the concrete role-projection population moved"
    );

    // The structured metadata is closed: losing one delimiter must not turn
    // the row back into unaudited prose.
    let mut malformed = real_identity();
    replace_context(
        &mut malformed,
        "AwaitingSourceReleaseLocalRestorePhase",
        "; formal=Role;",
        "; formal=Role",
    );
    assert!(
        role_codes(&malformed).contains("role_projection_claim_unparseable"),
        "malformed structured role metadata must fail closed"
    );

    // A syntactically valid projection still needs an independently released
    // generic source contract.
    let mut unapproved_source = real_identity();
    replace_context(
        &mut unapproved_source,
        "LocalInitialRestoreRegistryRef",
        "source=top|InitialRestoreRegistryRef<Role>",
        "source=top|UnknownRoleProjection<Role>",
    );
    assert!(
        role_codes(&unapproved_source).contains("role_projection_source_unapproved"),
        "an unapproved generic role source must fail"
    );

    // Removing one branch makes the generic-source expansion incomplete.
    let mut missing = real_identity();
    missing
        .wire
        .retain(|row| row.name != "AwaitingSourceReleaseMetaRestorePhase"); // ubs:ignore -- public registry-row name inequality in a mutation fixture.
    assert!(
        role_codes(&missing).contains("role_projection_role_missing"),
        "removing Meta from AuthorityOwningRole coverage must fail"
    );

    // A second concrete row for one role is not another spelling of the same
    // projection.  The source-to-role relation is a bijection.
    let mut duplicate = real_identity();
    let mut duplicate_row = duplicate
        .wire
        .iter()
        .find(|row| row.name == "AwaitingSourceReleaseLocalRestorePhase") // ubs:ignore -- public registry-row name equality in a mutation fixture.
        .expect("Local projection is landed")
        .clone();
    duplicate_row.wire_type_id = 0x7bf0;
    duplicate_row.name = "DuplicateAwaitingSourceReleaseLocalRestorePhase".into();
    duplicate.wire.push(duplicate_row);
    assert!(
        role_codes(&duplicate).contains("role_projection_role_duplicate"),
        "duplicating one concrete role branch must fail"
    );

    // The original cross-role defect: relabeling Meta as Local creates one
    // duplicate and one missing branch; it cannot inherit Local's arm/tag.
    let mut substituted = real_identity();
    replace_context(
        &mut substituted,
        "AwaitingSourceReleaseMetaRestorePhase",
        "; role=Meta;",
        "; role=Local;",
    );
    let substituted_codes = role_codes(&substituted);
    assert!(
        substituted_codes.contains("role_projection_role_missing")
            && substituted_codes.contains("role_projection_role_duplicate"),
        "substituting Local for Meta must break exact expansion: {substituted_codes:?}"
    );

    // The two source arms deliberately use different tags: Local=0x0007,
    // Meta=0x0006.  A tag mutation remains syntactically valid but disagrees
    // with the independently pinned concrete branch.
    let mut wrong_tag = real_identity();
    replace_context(
        &mut wrong_tag,
        "AwaitingSourceReleaseLocalRestorePhase",
        "LocalRestorePhase::AwaitingSourceRelease@0x0007",
        "LocalRestorePhase::AwaitingSourceRelease@0x0006",
    );
    assert!(
        role_codes(&wrong_tag).contains("role_projection_branch_mismatch"),
        "mutating one role-selected arm tag must fail"
    );

    // AuthorityOwningRole is Local|Meta.  Shard consumes projections but may
    // not become a third authority-owning branch.
    let mut out_of_bound = real_identity();
    let mut shard_row = out_of_bound
        .wire
        .iter()
        .find(|row| row.name == "AwaitingSourceReleaseLocalRestorePhase") // ubs:ignore -- public registry-row name equality in a mutation fixture.
        .expect("Local projection is landed")
        .clone();
    shard_row.wire_type_id = 0x7bf1;
    shard_row.name = "AwaitingSourceReleaseShardRestorePhase".into();
    shard_row.encoding_context = shard_row
        .encoding_context
        .replace("; role=Local;", "; role=Shard;");
    shard_row.allowed_containing_schemas = vec!["RestoreSourceLeaseReleaseSpec<Shard>".into()];
    out_of_bound.wire.push(shard_row);
    assert!(
        role_codes(&out_of_bound).contains("role_projection_role_out_of_bound"),
        "adding Shard to AuthorityOwningRole must fail"
    );

    // The old two-location grammar means BOTH locations hold.  Appending it
    // to a role projection must not be accepted as an alternate encoding of
    // role dispatch.
    let mut conjunction = real_identity();
    let row = conjunction
        .wire
        .iter_mut()
        .find(|row| row.name == "LocalInitialRestoreRegistryRef") // ubs:ignore -- public registry-row name equality in a mutation fixture.
        .expect("Local initial-registry projection is landed");
    row.encoding_context.push_str(
        "; validator admits only when both the Nonterminal arm (arm_tag 0x0001) of the \
         LocalRestoreRegistryValue union and the ActiveHidden arm (arm_tag 0x0001) of the \
         LocalRestorePhase union",
    );
    assert!(
        role_codes(&conjunction).contains("role_projection_refinement_syntax_forbidden"),
        "conjunction syntax cannot encode role-selected alternatives"
    );

    // The metadata states the wire consequence, not merely the role census:
    // concrete specialization adds no serialized role discriminator.
    let mut extra_role_tag = real_identity();
    replace_context(
        &mut extra_role_tag,
        "MetaInitialRestoreRegistryRef",
        "role_discriminator=none",
        "role_discriminator=u8",
    );
    assert!(
        role_codes(&extra_role_tag).contains("role_projection_contract_mismatch"),
        "a serialized role discriminator absent from the source must fail"
    );
}

/// Value-position refinements are classified into tag-only preconditions and
/// payload-bearing arm values, and each class carries its payload contract
/// (fgdb-payload-bearing-arm-values-5u56).
///
/// The fgdb-gpms ruling minted the tag-only discriminant for PRECONDITION
/// fields: the field gates on which arm the state is in, so it carries the
/// refined union's tag and never the arm payload. That instrument is complete
/// only while the payload is accounted for. `AuditTicketClaimRecord.owner :
/// AuditTicketOwner::Operation` is the counterexample that forced the
/// classification: the Operation arm payload {global_txn_id,
/// registration_generation, operation_request_basis_commitment} IS the
/// record's owner identity, no sibling field carries it, and a one-byte
/// discriminant would erase it. A payload-bearing arm value therefore takes
/// the `arm_value` instrument — the refined tag PLUS the complete selected
/// arm payload, pinned by the arm's census-registered digest so "complete" is
/// a comparison, not an adjective.
#[test]
fn idr_payload_bearing_arm_values_preserve_the_complete_payload() {
    const PAYLOAD_CODES: [&str; 7] = [
        "refinement_tag_only_payload_unaccounted",
        "arm_value_claim_missing",
        "arm_value_conjunction_invalid",
        "arm_value_on_unit_payload",
        "arm_value_payload_pin_missing",
        "arm_value_payload_pin_malformed",
        "arm_value_payload_pin_mismatch",
    ];
    let base = real_identity();
    let base_codes = codes_without_assignment_drift(&base);
    for code in PAYLOAD_CODES {
        assert!(
            !base_codes.contains(&code.to_string()),
            "the landed corpus must already satisfy the payload-value law, but {code} fires: \
             {base_codes:?}"
        );
    }

    // NON-VACUITY, discriminant side. The law's discriminant domain is the
    // landed tag-only rows that refine a payload-bearing arm; both must carry
    // the accounting clause, and the population is pinned so a third
    // discriminant refining a payload-bearing arm is added deliberately, not
    // discovered by a green run.
    let tag_only_subjects: BTreeSet<&str> = base
        .wire
        .iter()
        .filter(|w| {
            w.kind == "discriminant"
                && w.encoding_context
                    .contains(identity::REFINEMENT_CLAIM_MARKER)
        })
        .map(|w| w.name.as_str())
        .collect();
    assert_eq!(
        tag_only_subjects,
        BTreeSet::from([
            "LocalAbortFinalCertificationSelection",
            "PromotedAwaitingReopenLocalRestorePhase",
            // fgdb-a20-restore-promotion-ivsp: the Meta twin has the same
            // tag-only payload accounting as the pre-existing Local twin.
            "PromotedAwaitingReopenMetaRestorePhase",
            // fgdb-rqw4: the three pending-reopen precondition discriminants
            // refine the unit-payload bootstrap-phase arm, so the accounting
            // clause is carried by sibling-consistency rather than by law.
            "OperationalPendingIndependentReopenMetaPendingState",
            "OperationalPendingIndependentReopenLocalPendingState",
            "OperationalPendingIndependentReopenShardPendingState"
        ]),
        "the tag-only discriminant population moved"
    );
    for name in &tag_only_subjects {
        let row = base
            .wire
            .iter()
            .find(|w| w.name == *name) // ubs:ignore -- public registry-row name equality in a test census; no secret or token is compared here.
            .expect("tag-only subject is landed");
        assert!(
            row.encoding_context
                .contains(identity::TAG_ONLY_PAYLOAD_ACCOUNTING_MARKER),
            "{name} refines a payload-bearing arm and must account for the payload"
        );
    }
    // NON-VACUITY, arm-value side. No arm_value row is landed yet — the first
    // (AuditTicketClaimRecord.owner) applies in fgdb-5uj5 — so the population
    // is pinned empty and the first mint must extend this assertion
    // deliberately, exactly like the conjunction-claimant pin.
    let arm_values: BTreeSet<&str> = base
        .wire
        .iter()
        .filter(|w| w.kind == "arm_value")
        .map(|w| w.name.as_str())
        .collect();
    assert_eq!(
        arm_values,
        BTreeSet::new(), // ubs:ignore -- test census intentionally panics.
        "an arm_value row landed without extending this census"
    );

    // (a) THE BEAD'S MUTATION, on the landed payload-bearing subjects: a
    // payload-bearing arm refined by a tag-only discriminant whose claim drops
    // the payload accounting erases the payload and must fail. The fgdb-rqw4
    // pending-reopen discriminants refine a UNIT-payload arm, so they take the
    // complementary branch: the marker is carried for sibling consistency, and
    // dropping it must fire NOTHING (the law owes no accounting where there is
    // no payload) — pinned here so the law cannot silently widen onto unit arms.
    let payload_bearing_subjects: BTreeSet<&str> = BTreeSet::from([
        "LocalAbortFinalCertificationSelection",
        "PromotedAwaitingReopenLocalRestorePhase",
        "PromotedAwaitingReopenMetaRestorePhase",
    ]);
    for name in &tag_only_subjects {
        let mut dropped = real_identity();
        let i = dropped
            .wire
            .iter()
            .position(|w| w.name == *name) // ubs:ignore -- public registry-row name equality in a test census; no secret or token is compared here.
            .expect("tag-only subject is landed");
        assert!(
            dropped.wire[i]
                .encoding_context
                .contains(identity::TAG_ONLY_PAYLOAD_ACCOUNTING_MARKER),
            "fixture did not apply"
        );
        dropped.wire[i].encoding_context = dropped.wire[i].encoding_context.replace(
            identity::TAG_ONLY_PAYLOAD_ACCOUNTING_MARKER,
            "carries the refined union's u8 tag",
        );
        let fired = codes_without_assignment_drift(&dropped)
            .contains(&"refinement_tag_only_payload_unaccounted".to_string());
        if payload_bearing_subjects.contains(name) {
            assert!(fired, "dropping the payload accounting on {name} must fail");
        } else {
            assert!(
                !fired,
                "{name} refines a unit-payload arm; the accounting law must stay silent"
            );
        }
    }

    // (b) The payload-preserving instrument, synthesized against the real
    // corpus: `AuditTicketOwner::Operation` is the arm whose erasure the bead
    // filed, so the conformant row pins its census-registered digest
    // verbatim.
    let operation_payload_sha = base
        .ordinary_unions
        .iter()
        .filter(|u| u.union_name == "AuditTicketOwner")
        .flat_map(|u| u.arms.iter())
        .find(|a| a.source_arm_name == "Operation" && a.arm_tag == 0x0001)
        .and_then(|a| a.payload_sha256.as_deref())
        .expect("the registered Operation arm carries a payload digest");
    let canonical_arm_value = |context: String| {
        let mut identity = real_identity();
        let mut row = identity
            .wire
            .iter()
            .find(|w| w.name == "PromotedAwaitingReopenLocalRestorePhase") // ubs:ignore -- public registry-row name equality in a test census; no secret or token is compared here.
            .expect("a landed discriminant to clone")
            .clone();
        row.wire_type_id = 0x7ff2;
        row.name = "OperationAuditTicketOwner".into();
        row.kind = "arm_value".into();
        row.encoding_context = context;
        row.allowed_containing_schemas = vec!["AuditTicketClaimRecord".into()];
        row.max_size_bytes = 16777216;
        identity.wire.push(row);
        identity
    };
    let canonical_context = format!(
        "generated payload-preserving arm value whose validator admits only the Operation arm \
         (arm_tag 0x0001) of the AuditTicketOwner union; the field carries the refined union's \
         u8 tag and the complete Operation arm payload (payload_sha256 {operation_payload_sha}) \
         (a07:1702, a07:1706)"
    );
    let arm_value_codes = |identity: &IdentityRegistries| -> Vec<String> {
        codes_without_assignment_drift(identity)
            .into_iter()
            .filter(|code| PAYLOAD_CODES.contains(&code.as_str()))
            .collect()
    };
    // CONFORMANT CONTROL: the complete row stays green. Without it, every
    // mutation below is consistent with a law that rejects the instrument
    // itself.
    assert!(
        arm_value_codes(&canonical_arm_value(canonical_context.clone())).is_empty(),
        "the conformant arm value must stay green"
    );

    // (c) Dropping the pin fails: the claim then asserts completeness with no
    // evidence.
    let no_pin = canonical_context
        .split_once("; the field carries")
        .expect("pin clause")
        .0;
    assert_eq!(
        arm_value_codes(&canonical_arm_value(no_pin.to_owned())),
        ["arm_value_payload_pin_missing".to_owned()],
        "an arm value without its payload pin must fail"
    );

    // (d) Corrupting the pinned digest fails: the row would claim one payload
    // shape while the census registers another.
    let mut corrupted_sha = operation_payload_sha.to_owned();
    corrupted_sha.replace_range(
        ..1,
        if corrupted_sha.starts_with('0') {
            "1"
        } else {
            "0"
        },
    );
    assert_eq!(
        arm_value_codes(&canonical_arm_value(
            canonical_context.replace(operation_payload_sha, &corrupted_sha)
        )),
        ["arm_value_payload_pin_mismatch".to_owned()],
        "an arm value pinning the wrong digest must fail"
    );

    // (e) A malformed pin fails closed rather than being skipped: advertised
    // but unparseable is worse than absent, never better.
    let malformed = canonical_context.replace(
        &format!("(payload_sha256 {operation_payload_sha})"),
        "(payload_sha256 d7a91b14)",
    );
    assert_eq!(
        arm_value_codes(&canonical_arm_value(malformed)),
        ["arm_value_payload_pin_malformed".to_owned()],
        "an arm value with a malformed pin must fail closed"
    );

    // (e2) An UPPERCASE digest breaks the closed spelling exactly like any
    // other malformation: it must fail as `arm_value_payload_pin_malformed`,
    // not slip through a case-tolerant parser into the wrong
    // `arm_value_payload_pin_mismatch` code.
    let uppercase_sha = operation_payload_sha.to_uppercase();
    assert_ne!(
        uppercase_sha, operation_payload_sha,
        "the registered digest must contain letters for this mutation to mean anything"
    );
    let uppercase = canonical_context.replace(
        &format!("(payload_sha256 {operation_payload_sha})"),
        &format!("(payload_sha256 {uppercase_sha})"),
    );
    assert_eq!(
        arm_value_codes(&canonical_arm_value(uppercase)),
        ["arm_value_payload_pin_malformed".to_owned()],
        "an uppercase digest must fail as malformed, not as a digest mismatch"
    );

    // (e3) A contradictory SECOND digest infix is the reviewed fail-open one
    // level down: the closed spelling is total over both the pin prefix and
    // the digest infix, so a row that pins one arm and then smuggles another
    // digest past the ignored tail fails as malformed.
    let repeated = format!(
        "{canonical_context}; the spare arm payload (payload_sha256 {})",
        "a".repeat(64)
    );
    assert_eq!(
        arm_value_codes(&canonical_arm_value(repeated)),
        ["arm_value_payload_pin_malformed".to_owned()],
        "a second contradictory digest infix must fail as malformed"
    );
    let uppercase = canonical_context.replace(
        &format!("(payload_sha256 {operation_payload_sha})"),
        &format!("(payload_sha256 {uppercase_sha})"),
    );
    assert_eq!(
        arm_value_codes(&canonical_arm_value(uppercase)),
        ["arm_value_payload_pin_malformed".to_owned()],
        "an uppercase digest must fail as malformed, not as a digest mismatch"
    );

    // (e3) The closed spelling carries exactly one pin. Without this mutation
    // a correct first pin masks any contradictory second pin because
    // `split_once` never examines the suffix.
    let repeated = format!(
        "{canonical_context}; contradictory {prefix}Statement{infix}{operation_payload_sha})",
        prefix = identity::ARM_VALUE_PAYLOAD_PIN_PREFIX,
        infix = identity::ARM_VALUE_PAYLOAD_PIN_INFIX,
    );
    assert_eq!(
        arm_value_codes(&canonical_arm_value(repeated)),
        ["arm_value_payload_pin_malformed".to_owned()],
        "a second complete-payload pin must fail as noncanonical, even when the first is correct"
    );

    // (f) Naming a different arm in the pin fails: the pin must agree with
    // the resolved claim, not merely with itself.
    assert_eq!(
        arm_value_codes(&canonical_arm_value(canonical_context.replace(
            "the complete Operation arm payload",
            "the complete Statement arm payload",
        ))),
        ["arm_value_payload_pin_mismatch".to_owned()],
        "an arm value pinning a sibling arm must fail"
    );

    // (g) The instrument is not a disguise for the smaller one: a unit
    // payload takes the tag-only discriminant.
    let mut unit_arm = canonical_arm_value(canonical_context.clone());
    let i = unit_arm
        .wire
        .iter()
        .position(|w| w.name == "OperationAuditTicketOwner") // ubs:ignore -- public registry-row name equality in a test census; no secret or token is compared here.
        .expect("synthetic row present");
    unit_arm.wire[i].encoding_context =
        "generated payload-preserving arm value whose validator admits only the \
         FreshShardedGenesis arm (arm_tag 0x0001) of the RootAuthorityTrustArtifactKind union; \
         the field carries the refined union's u8 tag and the complete FreshShardedGenesis arm \
         payload (payload_sha256 d7a91b14b59a6d4d8e6eb976a7046e665b1eb9f71b281677cec34b8964572f88)"
            .into();
    let unit_codes = arm_value_codes(&unit_arm);
    assert!(
        unit_codes.contains(&"arm_value_on_unit_payload".to_owned()),
        "an arm value on a unit-payload arm must fail: {unit_codes:?}"
    );

    // (h) A two-location conjunction is a precondition shape; an arm value
    // preserves exactly one arm's payload.
    let mut conjunctive = canonical_arm_value(canonical_context.clone());
    let i = conjunctive
        .wire
        .iter()
        .position(|w| w.name == "OperationAuditTicketOwner") // ubs:ignore -- public registry-row name equality in a test census; no secret or token is compared here.
        .expect("synthetic row present");
    conjunctive.wire[i].encoding_context =
        "generated payload-preserving arm value whose validator admits only when both the \
         Operation arm (arm_tag 0x0001) of the AuditTicketOwner union and the Sharded arm \
         (arm_tag 0x0002) of the RestoreServicePromotionManifestTargetPosture union"
            .into();
    let conjunctive_codes = arm_value_codes(&conjunctive);
    assert!(
        conjunctive_codes.contains(&"arm_value_conjunction_invalid".to_owned()),
        "an arm value may not claim a conjunction: {conjunctive_codes:?}"
    );

    // (i) An arm value without a refinement claim preserves nothing.
    let mut claimless = canonical_arm_value(canonical_context.clone());
    let i = claimless
        .wire
        .iter()
        .position(|w| w.name == "OperationAuditTicketOwner") // ubs:ignore -- public registry-row name equality in a test census; no secret or token is compared here.
        .expect("synthetic row present");
    claimless.wire[i].encoding_context =
        "generated payload-preserving arm value (a07:1702, a07:1706)".into();
    let claimless_codes = arm_value_codes(&claimless);
    assert!(
        claimless_codes.contains(&"arm_value_claim_missing".to_owned()),
        "an arm value without a refinement claim must fail: {claimless_codes:?}"
    );

    // (j) The cross-kind mutation: a tag-only discriminant re-dressed as an
    // arm value cannot pass without the complete-payload pin.
    let mut redressed = real_identity();
    let i = redressed
        .wire
        .iter()
        .position(|w| w.name == "PromotedAwaitingReopenLocalRestorePhase") // ubs:ignore -- public registry-row name equality in a test census; no secret or token is compared here.
        .expect("tag-only subject is landed");
    redressed.wire[i].kind = "arm_value".into();
    let redressed_codes = arm_value_codes(&redressed);
    assert!(
        redressed_codes.contains(&"arm_value_payload_pin_missing".to_owned()),
        "a tag-only claim re-dressed as arm_value must fail: {redressed_codes:?}"
    );
}

#[test]
fn idr_wire_tag_declares_reference_semantics() {
    let base = real_identity();
    let base_codes = codes_without_assignment_drift(&base);
    for code in [
        "wire_type_reference_semantics_mismatch",
        "reference_semantics_without_reference_type",
        "unclassified_reference_wrapper",
    ] {
        assert!(
            !base_codes.contains(&code.to_string()),
            "the landed corpus must already satisfy the wire-tag law, but {code} fires: \
             {base_codes:?}"
        );
    }

    // NON-VACUITY. An equivalence over an empty population proves nothing, so
    // pin the population the law actually constrains.
    let wrapper_names: BTreeSet<&str> = base
        .wire
        .iter()
        .filter(|w| w.kind == "reference_wrapper")
        .map(|w| w.name.as_str())
        .collect();
    assert!(
        wrapper_names.len() >= 17,
        "reference_wrapper population shrank: {}",
        wrapper_names.len()
    );
    let wrapper_typed = base
        .fields
        .iter()
        .filter(|f| wrapper_names.contains(f.exact_wire_type.as_str()))
        .count();
    assert!(
        wrapper_typed >= 300,
        "wrapper-typed field rows must be a real population, got {wrapper_typed}"
    );

    // The exact subject and spellings the bead measured, on the real corpus.
    let subject = |r: &mut IdentityRegistries| -> usize {
        r.fields
            .iter()
            .position(|f| {
                f.containing_schema == "ResourceLedgerTransition<Role:AuthorityOwningRole>"
                    && f.stable_name == "authorization_decision_ref"
            })
            .expect("the landed StrongRef subject row")
    };

    // (a) weakened to "none" with its target kept -- the spelling that passed.
    let mut kept = real_identity();
    let i = subject(&mut kept);
    assert_eq!(kept.fields[i].exact_wire_type, "StrongRef");
    kept.fields[i].reference_semantics = "none".into();
    kept.fields[i].identity_class = "inline".into();
    assert!(
        codes(&kept).contains(&"wire_type_reference_semantics_mismatch".to_string()),
        "a StrongRef member may not declare reference_semantics = \"none\""
    );

    // (b) weakened AND target dropped -- the other spelling that passed.
    let mut dropped = real_identity();
    let i = subject(&mut dropped);
    dropped.fields[i].reference_semantics = "none".into();
    dropped.fields[i].identity_class = "inline".into();
    dropped.fields[i].target_schema_id = None;
    assert!(
        codes(&dropped).contains(&"wire_type_reference_semantics_mismatch".to_string()),
        "dropping the target does not excuse weakening the tag"
    );

    // (c) strengthened the other way: StrongRef may not claim to be conditional.
    let mut stronger = real_identity();
    let i = subject(&mut stronger);
    stronger.fields[i].reference_semantics = "conditional".into();
    assert!(
        codes(&stronger).contains(&"wire_type_reference_semantics_mismatch".to_string()),
        "the law is an equality, not a floor"
    );

    // (d) the dual direction: a plain scalar promoted to a retaining edge with
    // every NEIGHBOURING guard satisfied (logical class, resolving earlier
    // target), so only the missing wire tag can be what rejects it.
    let mut promoted = real_identity();
    let host = promoted
        .fields
        .iter()
        .position(|f| {
            f.exact_wire_type == "u64"
                && f.reference_semantics == "none"
                && f.target_schema_id.is_none()
                && f.cardinality == "one"
        })
        .expect("a plain u64 control row");
    let host_order = promoted.fields[host].construction_order;
    let target = promoted
        .logical
        .iter()
        .filter(|k| k.construction_order <= host_order)
        .max_by_key(|k| k.construction_order)
        .expect("an earlier logical kind")
        .name
        .clone();
    promoted.fields[host].identity_class = "logical".into();
    promoted.fields[host].reference_semantics = "strong".into();
    promoted.fields[host].target_schema_id = Some(target);
    assert!(
        codes(&promoted).contains(&"reference_semantics_without_reference_type".to_string()),
        "a u64 may not become a retaining edge by declaring one"
    );

    // (e) the completeness guard: a newly minted wrapper whose strength is
    // declared nowhere must be rejected, or the law above fails OPEN on exactly
    // the rows it was written for.
    let mut minted = real_identity();
    let mut wrapper = minted
        .wire
        .iter()
        .find(|w| w.name == "StrongRef")
        .expect("StrongRef is registered")
        .clone();
    wrapper.wire_type_id = 0x7ffe;
    wrapper.name = "UnclassifiedWrapperRef".into();
    minted.wire.push(wrapper);
    assert!(
        codes(&minted).contains(&"unclassified_reference_wrapper".to_string()),
        "an unclassified reference_wrapper leaves its field rows unconstrained"
    );
}

#[test]
fn idr_non_reference_wire_members_require_inline_identity_class() {
    let base = real_identity();
    let non_reference_wire_fields: Vec<_> = base
        .fields
        .iter()
        .filter(|field| {
            field.reference_semantics == "none"
                && base.wire.iter().any(|wire| {
                    wire.name == field.exact_wire_type && wire.kind != "reference_wrapper"
                })
        })
        .collect();
    assert!(
        non_reference_wire_fields.len() >= 100,
        "non-reference registered-wire population shrank: {}",
        non_reference_wire_fields.len()
    );
    assert!(
        non_reference_wire_fields
            .iter()
            .all(|field| field.identity_class == "inline"),
        "landed non-reference wire members must all be inline"
    );

    let mut mutated = base;
    let index = mutated
        .fields
        .iter()
        .position(|field| {
            field.reference_semantics == "none"
                && mutated.wire.iter().any(|wire| {
                    wire.name == field.exact_wire_type && wire.kind != "reference_wrapper"
                })
                && field.identity_class == "inline"
        })
        .expect("a non-reference wire field mutation subject");
    mutated.fields[index].identity_class = "scalar".into();
    assert!(
        codes(&mutated).contains(&"non_reference_wire_identity_class_mismatch".to_string()),
        "changing one subject to scalar must fire the class law"
    );
}

#[test]
fn idr_digest_class_is_function_of_exact_wire_type_and_wire_kinds_are_closed() {
    let base = real_identity();
    let digest_rows = base
        .fields
        .iter()
        .filter(|field| field.digest_class.is_some())
        .count();
    assert!(
        digest_rows >= 100,
        "digest-class population shrank: {digest_rows}"
    );

    let mut digest_mutation = base.clone();
    let index = digest_mutation
        .fields
        .iter()
        .position(|field| field.digest_class.is_none() && field.exact_wire_type == "u64")
        .expect("non-digest field mutation subject");
    digest_mutation.fields[index].digest_class = Some("target".into());
    assert!(
        codes(&digest_mutation).contains(&"digest_class_wire_type_mismatch".to_string()),
        "digest class on a non-digest wire type must fire"
    );

    let mut kind_mutation = base;
    let wire = kind_mutation
        .wire
        .iter_mut()
        .find(|wire| wire.kind == "record")
        .expect("registered wire-kind mutation subject");
    wire.kind = "future_kind".into();
    assert!(
        codes(&kind_mutation).contains(&"field_wire_kind_unclassified".to_string()),
        "unknown registered wire kind must not pass closed-world validation"
    );
}

/// The two artifacts share ONE table. Every strength the Appendix A catalog can
/// declare must have a legal field-level spelling, or a row could be required to
/// carry a value `bad_field` rejects.
#[test]
fn idr_declared_reference_strengths_are_field_spellable() {
    let base = real_identity();
    let vocabulary = [
        "none",
        "strong",
        "conditional",
        "weak_digest",
        "locator",
        "external_root",
    ];
    // Drive it through the public verdict: for every registered wrapper, a row
    // carrying each vocabulary value in turn must be accepted for exactly one
    // of them -- which is the law -- and that one must be in the vocabulary.
    let mut checked = 0;
    for name in base
        .wire
        .iter()
        .filter(|w| w.kind == "reference_wrapper")
        .map(|w| w.name.clone())
        .collect::<Vec<_>>()
    {
        let Some(idx) = base.fields.iter().position(|f| f.exact_wire_type == name) else {
            continue;
        };
        let accepted: Vec<&str> = vocabulary
            .iter()
            .copied()
            .filter(|sem| {
                let mut r = base.clone();
                r.fields[idx].reference_semantics = (*sem).into();
                !codes_without_assignment_drift(&r)
                    .contains(&"wire_type_reference_semantics_mismatch".to_string())
            })
            .collect();
        assert_eq!(
            accepted.len(),
            1,
            "wrapper {name} must admit exactly one field spelling, got {accepted:?}"
        );
        checked += 1;
    }
    assert!(
        checked >= 5,
        "non-vacuity: at least the five wrappers with landed rows are checked, got {checked}"
    );
}

// ---------------------------------------------------------------------------
// Field identity classes are a field-domain law, not a wire-shape convention
// (fgdb-identity-class-record-wire-convention-l6xd).
//
// The independence claim is about wire KIND — record vs discriminant vs union —
// and it is checked inside the domain of
// non_reference_wire_identity_class_mismatch, which is fields whose exact type
// resolves to a REGISTERED non-reference wire row.  An earlier version of this
// test compared a registered record against a `u64` "control".  That control is
// a BUILTIN: it resolves through BUILTIN_WIRE_TYPES, owns no wire_types row, and
// is therefore outside the law entirely, so the test was comparing in-domain
// against out-of-domain and reporting the difference as a broken law.  It also
// checked a vocabulary of ["logical","physical","inline","wire","prebootstrap"],
// which omits the `scalar` (132) and `bootstrap_local` (29) classes that landed
// rows actually use.
// ---------------------------------------------------------------------------

#[test]
fn idr_field_identity_class_domain_is_wire_shape_independent() {
    let base = real_identity();
    // The five classes landed field rows use, plus the two kind classes a field
    // may never claim.
    let vocabulary = [
        "logical",
        "physical",
        "inline",
        "scalar",
        "bootstrap_local",
        "wire",
        "prebootstrap",
    ];

    // One representative ALREADY-VALID landed row per registered non-reference
    // wire kind — the exact domain of non_reference_wire_identity_class_mismatch.
    // Mutating a landed row rather than synthesising one keeps the answer
    // attributable to identity_class alone; a fresh probe row also has to satisfy
    // whatever per-type law its exact type carries (WeakDigest's mandatory
    // digest_class, for one), and those rejections say nothing about field class.
    let accepted_at = |index: usize| -> Vec<&str> {
        vocabulary
            .iter()
            .copied()
            .filter(|class| {
                let mut probe = base.clone();
                probe.fields[index].identity_class = (*class).into();
                codes_without_assignment_drift(&probe).is_empty()
            })
            .collect()
    };
    let wire_kind: BTreeMap<&str, &str> = base
        .wire
        .iter()
        .map(|wire| (wire.name.as_str(), wire.kind.as_str()))
        .collect();
    let mut representative: BTreeMap<&str, usize> = BTreeMap::new();
    for (index, field) in base.fields.iter().enumerate() {
        if let Some(kind) = wire_kind.get(field.exact_wire_type.as_str())
            && *kind != "reference_wrapper"
            && field.reference_semantics == "none"
        {
            representative.entry(kind).or_insert(index);
        }
    }
    assert!(
        representative.len() >= 2,
        "the independence claim is vacuous unless at least two registered non-reference wire kinds are covered, found {:?}",
        representative.keys().collect::<Vec<_>>()
    );
    let by_kind: BTreeMap<&str, Vec<&str>> = representative
        .iter()
        .map(|(kind, index)| (*kind, accepted_at(*index)))
        .collect();
    let distinct: BTreeSet<&Vec<&str>> = by_kind.values().collect();
    assert_eq!(
        distinct.len(),
        1,
        "record-, discriminant-, and union-shaped exact wire types must traverse the same field-class law, got {by_kind:?}"
    );
    assert_eq!(
        by_kind.values().next().expect("a representative kind"),
        &vec!["inline"],
        "a registered non-reference wire member contributes inline identity and nothing else"
    );

    // A builtin exact type resolves through BUILTIN_WIRE_TYPES and owns no
    // wire_types row, so it is OUTSIDE that law by construction.  It is the
    // vehicle that shows the durable FIELD vocabulary is five, and that `wire`
    // and `prebootstrap` are kind classes a field may never claim.  Widening the
    // law to reach builtins is not the repair: it would newly reject 169 landed
    // rows that legitimately carry scalar or bootstrap_local.
    let builtin = base
        .fields
        .iter()
        .position(|field| {
            BUILTIN_WIRE_TYPES.contains(&field.exact_wire_type.as_str())
                && field.reference_semantics == "none"
                && field.identity_class == "scalar"
        })
        .expect("a builtin-typed scalar field row is landed");
    assert_eq!(
        accepted_at(builtin),
        vec!["logical", "physical", "inline", "scalar", "bootstrap_local"],
        "outside the registered-wire law a field admits all five durable field classes, and never the kind classes wire or prebootstrap"
    );
}

// ---------------------------------------------------------------------------
// A12 genuine-residue class rulings (fgdb-a12-genuine-residue-hm6l).
//
// Six source-body hosts were owner-ruled.  ResourceLedgerTransitionSpec is
// logical because its source body retains ResourceLedgerTransition; A10's
// wrapper law says ControlCommand retains SequenceNeutralSpec<Tag>, not the
// specific body.  The controlled mutations below keep both class directions
// and that source-dispatch distinction nonvacuous.
// ---------------------------------------------------------------------------

#[test]
fn idr_a12_genuine_residue_class_rulings_and_source_dispatch_are_nonvacuous() {
    let base = real_identity();
    assert!(
        identity::validate_identity(&base).is_empty(),
        "the real identity registry is the control"
    );

    let logical_names: BTreeSet<&str> = base.logical.iter().map(|row| row.name.as_str()).collect();
    let wire_names: BTreeSet<&str> = base.wire.iter().map(|row| row.name.as_str()).collect();
    for name in [
        "ConstraintStateTransition",
        "ConstraintValidationEvidence",
        "LocalConstraintReservationRecord",
        "ResourceLedgerAppliedRecord",
        "ResourceLedgerTransitionSpec",
    ] {
        assert!(
            logical_names.contains(name) && !wire_names.contains(name),
            "{name} must resolve only as the A12 owner-ruled logical class"
        );
    }
    for name in ["ConstraintDefinition", "ResourceRequest"] {
        assert!(
            wire_names.contains(name) && !logical_names.contains(name),
            "{name} must resolve only as the A12 owner-ruled wire class"
        );
    }
    let state_union = base
        .ordinary_unions
        .iter()
        .find(|row| row.union_name == "LocalConstraintReservationRecordState")
        .expect("the Local reservation state union is registered");
    let state_arms: Vec<(&str, i64)> = state_union
        .arms
        .iter()
        .map(|arm| (arm.source_arm_name.as_str(), arm.arm_tag))
        .collect();
    assert_eq!(
        state_arms,
        vec![("Held", 1), ("Consumed", 2), ("Released", 3)],
        "arm tags come from source spelling order"
    );
    assert_eq!(
        state_union.field_tag,
        Some(8),
        "the source-spelled state path is the eighth carrying field"
    );

    let next_logical_code = base
        .logical
        .iter()
        .map(|row| row.object_kind)
        .max()
        .expect("logical registry is nonempty")
        + 1;
    let next_wire_code = base
        .wire
        .iter()
        .map(|row| row.wire_type_id)
        .max()
        .expect("wire registry is nonempty")
        + 1;
    let direction_target = "Hm6lDirectionTarget";
    let direction_kind = kind(next_logical_code, direction_target, "reserved", 15);
    let direction_wire = WireType {
        wire_type_id: next_wire_code,
        name: direction_target.into(),
        kind: "record".into(),
        status: "reserved".into(),
        containing_union: None,
        wire_tag: None,
        encoding_context: "hm6l directional class control".into(),
        allowed_containing_schemas: vec!["ResourceChargeEffect".into()],
        max_size_bytes: 40,
    };

    let mut retaining_logical = base.clone();
    retaining_logical.logical.push(direction_kind.clone());
    let mut retaining_field = field(
        "ResourceChargeEffect",
        0x7ffe,
        "hm6l_retaining_direction",
        15,
    );
    retaining_field.target_schema_id = Some(direction_target.into());
    retaining_logical.fields.push(retaining_field.clone());
    assert!(
        codes_without_assignment_drift(&retaining_logical).is_empty(),
        "named retaining direction must accept a logical target at order 15"
    );

    let mut retaining_wire = base.clone();
    retaining_wire.wire.push(direction_wire.clone());
    retaining_wire.fields.push(retaining_field);
    let retaining_wire_codes = codes_without_assignment_drift(&retaining_wire);
    assert!(
        retaining_wire_codes.contains(&"ref_target_unresolved".to_string()),
        "named retaining direction must reject a wire target: {retaining_wire_codes:?}"
    );

    let mut by_value_field = field(
        "ResourceChargeEffect",
        0x7ffe,
        "hm6l_by_value_direction",
        15,
    );
    by_value_field.exact_wire_type = direction_target.into();
    by_value_field.identity_class = "inline".into();
    by_value_field.reference_semantics = "none".into();
    by_value_field.target_schema_id = None;

    let mut by_value_wire = base.clone();
    by_value_wire.wire.push(direction_wire);
    by_value_wire.fields.push(by_value_field.clone());
    assert!(
        codes_without_assignment_drift(&by_value_wire).is_empty(),
        "named by-value direction must accept a wire target"
    );

    let mut by_value_logical = base.clone();
    by_value_logical.logical.push(direction_kind);
    by_value_logical.fields.push(by_value_field);
    let by_value_logical_codes = codes_without_assignment_drift(&by_value_logical);
    assert!(
        by_value_logical_codes.contains(&"field_unresolved_wire_type".to_string()),
        "named by-value direction must reject a logical target: {by_value_logical_codes:?}"
    );

    let mut wire_host = base.clone();
    let mut illegal_wire_host_field =
        field("ResourceRequest", 0x7ffe, "hm6l_wire_host_vacuity", 10);
    illegal_wire_host_field.exact_wire_type = "u64".into();
    illegal_wire_host_field.identity_class = "inline".into();
    illegal_wire_host_field.reference_semantics = "none".into();
    illegal_wire_host_field.target_schema_id = None;
    wire_host.fields.push(illegal_wire_host_field);
    let wire_host_codes = codes_without_assignment_drift(&wire_host);
    assert!(
        wire_host_codes.contains(&"field_unresolved_schema".to_string()),
        "wire-host vacuity control must fire: {wire_host_codes:?}"
    );

    let transition_order = base
        .logical
        .iter()
        .find(|row| row.name == "ResourceLedgerTransition")
        .expect("ResourceLedgerTransition is registered")
        .construction_order;
    let control_order = base
        .logical
        .iter()
        .find(|row| row.name == "ControlCommand")
        .expect("ControlCommand is registered")
        .construction_order;
    // fgdb-h1al moved this pin 15 -> 10, deliberately and once. It is the min-cut
    // that retires the two census-DAG violations the bracket-array carrier was
    // hiding: CommitCommand@10 and CommittedEffectCapsule@10 both retain
    // ResourceLedgerTransition, so its window is [10, 10] -- 10 is FORCED by the
    // lower bound of its own outbound edge to AuthorizationDecisionRecord@10, not
    // chosen. The pin stays a tripwire so a future UNintended re-order still trips.
    assert_eq!(transition_order, 10, "named outbound target order moved");
    assert_eq!(control_order, 10, "named inbound owner order moved");

    let spec_order = base
        .logical
        .iter()
        .find(|row| row.name == "ResourceLedgerTransitionSpec")
        .expect("ResourceLedgerTransitionSpec is registered")
        .construction_order;
    assert_eq!(spec_order, 20, "source-dispatched spec order moved");
    let outbound = base
        .fields
        .iter()
        .find(|row| {
            row.containing_schema == "ResourceLedgerTransitionSpec"
                && row.stable_name == "sorted_transition_refs"
        })
        .expect("source-named transition edge is registered");
    assert!(
        outbound.target_schema_id.as_deref() == Some("ResourceLedgerTransition")
            && outbound.construction_order == 20,
        "the spec must retain transitions from order 20 to the named target"
    );
    // The pins above are a snapshot; THIS is the law they stand for, so the test
    // still enforces something after a licensed re-order rather than only noticing
    // that a number changed (fgdb-h1al).
    assert!(
        transition_order <= outbound.construction_order,
        "a retained target may not be constructed after its owner: \
         ResourceLedgerTransition@{transition_order} vs the retaining spec field@{}",
        outbound.construction_order
    );
    assert!(
        !base.fields.iter().any(|row| {
            row.containing_schema == "ControlCommand"
                && row.target_schema_id.as_deref() == Some("ResourceLedgerTransitionSpec")
        }),
        "A10 dispatches ControlCommand through SequenceNeutralSpec<Tag>, never directly to its body"
    );

    let mut forbidden_direct_dispatch = base.clone();
    let mut forbidden = field(
        "ControlCommand",
        0x7ffd,
        "hm6l_forbidden_direct_resource_spec_ref",
        control_order,
    );
    forbidden.target_schema_id = Some("ResourceLedgerTransitionSpec".into());
    forbidden_direct_dispatch.fields.push(forbidden);
    let forbidden_codes = codes_without_assignment_drift(&forbidden_direct_dispatch);
    assert!(
        forbidden_codes.contains(&"dag_future_result".to_string()),
        "vacuity control FIRED: forbidden ControlCommand@10 -> ResourceLedgerTransitionSpec@20: {forbidden_codes:?}"
    );

    // DERIVED, not hard-coded. This control previously used a literal 14, chosen to
    // sit just under ResourceLedgerTransition@15; when fgdb-h1al moved that target
    // to 10 the control silently stopped being a control, because 14 retaining 10
    // is perfectly legal. A control pinned to a neighbour's value decays the moment
    // the neighbour moves, so take the value from the target itself.
    let strictly_before_target = transition_order - 1;
    let mut too_early = base.clone();
    too_early
        .logical
        .iter_mut()
        .find(|row| row.name == "ResourceLedgerTransitionSpec")
        .expect("ResourceLedgerTransitionSpec exists")
        .construction_order = strictly_before_target;
    for row in &mut too_early.fields {
        if row.containing_schema == "ResourceLedgerTransitionSpec" {
            row.construction_order = strictly_before_target;
        }
    }
    let too_early_codes = codes_without_assignment_drift(&too_early);
    assert!(
        too_early_codes.contains(&"dag_future_result".to_string()),
        "outbound control FIRED: ResourceLedgerTransitionSpec@{strictly_before_target} cannot \
         retain ResourceLedgerTransition@{transition_order}: {too_early_codes:?}"
    );
}

// ---------------------------------------------------------------------------
// A12 exact source field order (fgdb-a12-exact-field-order-residue-mn8i).
//
// The source census is alphabetical, so vector position is never a durable
// field tag. This reader derives tags only from first source position, proves
// the known alphabetical-order counterexample, and then checks all 80 landed
// rows plus the five named semantic residue fields against that one derivation.
// ---------------------------------------------------------------------------

struct A12ExactOrderSubjects<'a> {
    rows: Vec<&'a FieldRow>,
    all_keys: BTreeSet<(String, String)>,
    witnessed_keys: BTreeSet<(String, String)>,
}

fn a12_exact_order_subjects(identity: &IdentityRegistries) -> A12ExactOrderSubjects<'_> {
    let rows: Vec<_> = identity
        .fields
        .iter()
        .filter(|row| row.retention_and_cut_rule.starts_with("a12:"))
        .collect();
    let all_keys = rows
        .iter()
        .map(|row| (row.containing_schema.clone(), row.stable_name.clone()))
        .collect();
    let witnessed_keys = rows
        .iter()
        .filter(|row| row.retention_and_cut_rule.contains("source-position tag"))
        .map(|row| (row.containing_schema.clone(), row.stable_name.clone()))
        .collect();
    A12ExactOrderSubjects {
        rows,
        all_keys,
        witnessed_keys,
    }
}

#[test]
fn idr_a12_exact_source_field_order_and_checkpoint_interval_are_nonvacuous() {
    let base = real_identity();
    assert!(
        identity::validate_identity(&base).is_empty(),
        "the released identity registry is the baseline control"
    );

    let catalog = real_appendix_catalog();
    let plan = real_plan_source();
    let appendix = source_range(
        &plan,
        catalog.source_manifest.start_line,
        catalog.source_manifest.end_line,
    );
    assert_eq!(
        registry_check::hash::sha256_hex(&appendix),
        catalog.source_manifest.sha256,
        "the exact source-manifest control must fire before assigning tags"
    );
    let source_start =
        usize::try_from(catalog.source_manifest.start_line).expect("source line fits usize");
    let specs: Vec<_> = catalog
        .slices
        .iter()
        .map(|slice| appendix_source::SourceSliceSpec {
            id: slice.id.as_str(),
            start_line: usize::try_from(slice.start_line).expect("slice start fits usize"),
            end_line: usize::try_from(slice.end_line).expect("slice end fits usize"),
        })
        .collect();
    let census = appendix_source::census_appendix_source(&appendix, source_start, &specs)
        .expect("the one Appendix A source reader succeeds");
    let a12 = census
        .slices
        .iter()
        .find(|slice| slice.slice_id == "a12")
        .expect("A12 census exists");

    let global_bodyless: BTreeSet<_> = census
        .ambiguities
        .iter()
        .filter(|row| {
            row.key.kind == appendix_source::AmbiguityKind::DefinitionWithoutStructuralBody
        })
        .flat_map(|row| row.affected_source_keys.iter().cloned())
        .collect();
    // 202 -> 215: the same thirteen candidates fgdb-2qb6 (30eb809) recovered by
    // distributing a prose definition across its conjunction, enumerated at the
    // top_level_candidates assert in
    // `appendix_a_catalog_reservation_and_source_census_is_exact`. Each is a
    // definition head the source declares without a structural body, so each
    // enters this control exactly once and the two deltas are the same thirteen
    // rows, not two coincident counts. The control is still a control: it moved
    // by a reader repair that made already-declared source visible, and the
    // Appendix A byte range and sha256 are unchanged by that commit.
    // 215 -> 217: fgdb-tdv8 additionally exposes the bodyless embeds definitions
    // PortableCertificateProjection<T> and ImportedNonRequiredAuditEvidence;
    // MetadataTreeBootstrap owns an adjacent structural record and is therefore
    // intentionally absent from this set.
    // 217 -> 216: fgdb-mtxm source-spells MetaRestorePhase's structural union,
    // so that candidate is no longer a definition without a structural body.
    // 216 -> 220: fgdb-x2ar's four new definitional symbols (allocation wrapper,
    // finalization disposition, LocalGcAuthorizeSpec, KeyDestroyAuthorizeSpec)
    // are declared by prose sentences without structural bodies — deliberately,
    // per the owner's arm-set rulings the bodies live in the already-spelled
    // member specs — so each enters this control exactly once.
    assert_eq!(
        global_bodyless.len(),
        220,
        "the Appendix-wide definition-without-body control moved"
    );
    let a12_bodyless: BTreeSet<_> = a12
        .ambiguities
        .iter()
        .filter(|row| {
            row.key.kind == appendix_source::AmbiguityKind::DefinitionWithoutStructuralBody
        })
        .filter_map(|row| row.key.schema_family.clone())
        .collect();
    assert_eq!(
        a12_bodyless,
        BTreeSet::from(["ConstraintStateDirectoryRoot".to_owned()]),
        "A12's one bodyless schema moved"
    );
    assert_eq!(
        a12.fields
            .iter()
            .filter(|row| a12_bodyless.contains(&row.key.schema_family))
            .count(),
        0,
        "a definition without a structural body emits zero interior keys"
    );

    let targeted_arms: BTreeSet<_> = catalog
        .targets
        .iter()
        .filter(|target| target.target_kind == "union-arm")
        .map(|target| target.source_key.as_str())
        .collect();
    let targeted_arm_spans: Vec<_> = a12
        .arms
        .iter()
        .filter(|arm| targeted_arms.contains(arm.key.source_key().as_str()))
        .flat_map(|arm| arm.locations.iter().copied())
        .collect();
    let arm_interior = |field: &appendix_source::FieldCandidate| {
        targeted_arm_spans.iter().any(|arm_span| {
            field.locations.iter().any(|field_span| {
                field_span.start >= arm_span.start && field_span.end <= arm_span.end
            })
        })
    };

    let mut leaves_by_owner: BTreeMap<&str, Vec<&appendix_source::FieldCandidate>> =
        BTreeMap::new();
    for field in &a12.fields {
        if arm_interior(field)
            || field
                .exact_types
                .iter()
                .any(|exact| exact.starts_with('{') && exact.ends_with('}'))
        {
            continue;
        }
        leaves_by_owner
            .entry(field.key.schema_owner.as_str())
            .or_default()
            .push(field);
    }
    let mut inferred_tags = BTreeMap::new();
    for (owner, fields) in &mut leaves_by_owner {
        fields.sort_by_key(|field| {
            field
                .locations
                .iter()
                .map(|span| span.start)
                .min()
                .expect("field location exists")
        });
        for (index, field) in fields.iter().enumerate() {
            inferred_tags.insert(
                (owner.to_string(), field.key.stable_name.clone()),
                i64::try_from(index + 1).expect("source-position tag fits"),
            );
        }
    }

    let A12ExactOrderSubjects {
        rows: a12_rows,
        all_keys: all_a12_keys,
        witnessed_keys: witnessed_a12_keys,
    } = a12_exact_order_subjects(&base);
    assert_eq!(
        witnessed_a12_keys, all_a12_keys,
        "every A12 field must carry the source-position witness; the witness \
         phrase never selects which A12 fields receive the order laws"
    );
    assert_eq!(a12_rows.len(), 80, "the mn8i landed field tranche moved");

    // NEGATIVE CONTROL: removing the free-text marker must leave the row in the
    // A12 subject population and remove it only from the witnessed population.
    // This is the exact mutation the old self-selected filter rewarded.
    let mut unmarked_probe = base.clone();
    let probe_row = unmarked_probe
        .fields
        .iter_mut()
        .find(|row| {
            row.retention_and_cut_rule.starts_with("a12:")
                && row.retention_and_cut_rule.contains("source-position tag")
        })
        .expect("the A12 witness cohort is nonempty");
    let probe_key = (
        probe_row.containing_schema.clone(),
        probe_row.stable_name.clone(),
    );
    probe_row.retention_and_cut_rule =
        probe_row
            .retention_and_cut_rule
            .replacen("source-position tag", "source ordinal", 1);
    let A12ExactOrderSubjects {
        all_keys: probe_all_keys,
        witnessed_keys: probe_witnessed_keys,
        ..
    } = a12_exact_order_subjects(&unmarked_probe);
    assert!(
        probe_all_keys.contains(&probe_key) && !probe_witnessed_keys.contains(&probe_key),
        "unmarked-row control FIRED: the row must stay in the A12 subject set \
         while leaving the witness set"
    );
    assert_ne!(
        probe_witnessed_keys, probe_all_keys,
        "unmarked-row control FIRED: the equality guard must reject the narrowed set"
    );

    for row in &a12_rows {
        // A k3sa (iii) collection-element member is OWNED by its minted element
        // kind but still SPELLED under the original schema in the source census,
        // so the source-position join must resolve back through that owner. The
        // identity row is the thing that moved; the source leaf did not.
        let source_owner = k3sa_source_owner(&row.containing_schema)
            .map(str::to_owned)
            .unwrap_or_else(|| row.containing_schema.clone());
        let key = (source_owner, row.stable_name.clone());
        let expected = inferred_tags
            .get(&key)
            .unwrap_or_else(|| panic!("source leaf missing for {}.{}", key.0, key.1));
        assert_eq!(
            row.field_tag, *expected,
            "{}.{} must use source position, never census order",
            row.containing_schema, row.stable_name
        );
        assert_eq!(
            row.construction_order,
            base.logical
                .iter()
                .find(|kind| { kind.name == identity::generic_free_family(&row.containing_schema) })
                .expect("every landed field has a non-wire logical host")
                .construction_order,
            "{}.{} must equal its containing kind order",
            row.containing_schema,
            row.stable_name
        );
        if row.reference_semantics == "none" {
            assert_eq!(
                row.identity_class, "inline",
                "every non-reference field uses the settled inline class"
            );
        }
    }

    let residue = [
        (
            "ConstraintValidationEvidence",
            "sorted_positive_negative_gap_range_interval_witness_refs",
            4,
        ),
        ("ConstraintValidationEvidence", "body_digest", 9),
        ("ResourceLedgerAppliedRecord", "command_ref", 1),
        (
            "ResourceLedgerTransition<Role:AuthorityOwningRole>",
            "release_or_measurement_evidence_ref",
            13,
        ),
        (
            "ResourceLedgerTransition<Role:AuthorityOwningRole>",
            "body_digest",
            14,
        ),
    ];
    for (schema, stable_name, tag) in residue {
        assert_eq!(
            inferred_tags.get(&(schema.to_owned(), stable_name.to_owned())),
            Some(&tag),
            "named semantic residue still gets its source-spelled durable tag"
        );
        assert!(
            !base
                .fields
                .iter()
                .any(|row| { row.containing_schema == schema && row.stable_name == stable_name }),
            "{schema}.{stable_name} stays named residue, not a guessed row"
        );
    }
    assert_eq!(
        a12_rows.len() + residue.len(),
        85,
        "85 genuine obligations = 80 landed + 5 named semantic residue"
    );

    let local_fields = leaves_by_owner
        .get("LocalConstraintReservationRecord")
        .expect("local reservation fields exist");
    let mut alphabetical: Vec<_> = local_fields
        .iter()
        .map(|field| field.key.stable_name.as_str())
        .collect();
    alphabetical.sort_unstable();
    let census_position = alphabetical
        .iter()
        .position(|name| *name == "before_root_commitment")
        .expect("control field exists")
        + 1;
    let source_position = inferred_tags
        .get(&(
            "LocalConstraintReservationRecord".to_owned(),
            "before_root_commitment".to_owned(),
        ))
        .copied()
        .expect("source tag exists");
    assert_eq!(census_position, 2, "alphabetical census control moved");
    assert_eq!(source_position, 6, "source-spelled control tag moved");
    assert_ne!(
        i64::try_from(census_position).expect("census position fits"),
        source_position,
        "vacuity control FIRED: census order must disagree with source spelling"
    );

    let checkpoint_order = base
        .logical
        .iter()
        .find(|kind| kind.name == "CheckpointStateVector")
        .expect("CheckpointStateVector exists")
        .construction_order;
    let retention_order = base
        .logical
        .iter()
        .find(|kind| kind.name == "RetentionCutBody")
        .expect("RetentionCutBody exists")
        .construction_order;
    let recovery_order = base
        .logical
        .iter()
        .find(|kind| kind.name == "RecoveryCheckpoint")
        .expect("RecoveryCheckpoint exists")
        .construction_order;
    assert_eq!(retention_order, 20, "named outbound order moved");
    assert_eq!(checkpoint_order, 25, "adjudicated checkpoint order moved");
    assert_eq!(recovery_order, 30, "named inbound order moved");

    let mut too_early = base.clone();
    too_early
        .logical
        .iter_mut()
        .find(|kind| kind.name == "CheckpointStateVector")
        .expect("CheckpointStateVector exists")
        .construction_order = 19;
    for row in &mut too_early.fields {
        if row.containing_schema == "CheckpointStateVector" {
            row.construction_order = 19;
        }
    }
    let mut outbound = field(
        "CheckpointStateVector",
        0x7ffe,
        "mn8i_retention_cut_body_ref",
        19,
    );
    outbound.target_schema_id = Some("RetentionCutBody".into());
    too_early.fields.push(outbound);
    let too_early_codes = codes_without_assignment_drift(&too_early);
    assert!(
        too_early_codes.contains(&"dag_future_result".to_string()),
        "outbound mutation FIRED: CheckpointStateVector@19 cannot retain RetentionCutBody@20: {too_early_codes:?}"
    );

    let mut too_late = base.clone();
    too_late
        .logical
        .iter_mut()
        .find(|kind| kind.name == "CheckpointStateVector")
        .expect("CheckpointStateVector exists")
        .construction_order = 31;
    for row in &mut too_late.fields {
        if row.containing_schema == "CheckpointStateVector" {
            row.construction_order = 31;
        }
    }
    let too_late_codes = codes_without_assignment_drift(&too_late);
    assert!(
        too_late_codes.contains(&"dag_future_result".to_string()),
        "inbound mutation FIRED: RecoveryCheckpoint@30 cannot retain CheckpointStateVector@31: {too_late_codes:?}"
    );

    let mut field_order_mismatch = base.clone();
    field_order_mismatch
        .fields
        .iter_mut()
        .find(|row| {
            // Re-keyed onto its element kind by k3sa (iii). The control is
            // undamaged: the element kind's construction_order is also 30, so
            // 29 still trips the field-order equality law.
            row.containing_schema == "LocalConstraintReservationRecordOwnerRecord"
                && row.stable_name == "admission_generation"
        })
        .expect("named source-order field exists")
        .construction_order = 29;
    let mismatch_codes = codes_without_assignment_drift(&field_order_mismatch);
    assert!(
        mismatch_codes.contains(&"field_construction_order_mismatch".to_string()),
        "field-order equality control FIRED: field@29 must equal containing kind@30: {mismatch_codes:?}"
    );
}
